# L6 — 2 класс: 50–70 слов, простые предложения, быт и природа, немного диалога.
L6 = [
 ("гроза", "Днём бы'ло жа'рко и ду'шно. Вдруг поду'л си'льный ве'тер, и не'бо потемне'ло. Над сте'пью сверкну'ла мо'лния, а пото'м загреме'л гром. Ерла'н с ма'мой успе'ли забежа'ть в дом. По кры'ше гро'мко застуча'л дождь. — Ма'ма, а почему' гром греми'т по'сле мо'лнии? — спроси'л Ерла'н. — Потому' что свет лети'т быстре'е зву'ка, — отве'тила ма'ма. Че'рез час гроза' ко'нчилась, и над по'лем засия'ла ра'дуга.", [("ду'шно", "Ду'шно — зна'чит жа'рко и не хвата'ет све'жего во'здуха."), ("мо'лния", "Мо'лния — э'то я'ркая вспы'шка в не'бе во вре'мя грозы'.")]),
 ("кот", "Па'па купи'л у'мный пылесо'с. Он сам е'здит по ко'мнатам и собира'ет пыль. Кот Ба'рсик снача'ла испуга'лся и спря'тался под дива'н. Пото'м он осторо'жно вы'глянул, поню'хал пылесо'с и запры'гнул на него' све'рху. Тепе'рь Ба'рсик ка'ждый день ката'ется на пылесо'се по всей кварти'ре. Он сиди'т ва'жно, как коро'ль на тро'не. — У на'шего кота' тепе'рь есть свой автомоби'ль! — смеётся Ди'ма.", [("пылесо'с", "Пылесо'с — э'то маши'на, кото'рая вса'сывает пыль и му'сор.")]),
 ("осень", "В октябре' в па'рке начался' листопа'д. Жёлтые и кра'сные ли'стья ти'хо лета'ют в во'здухе и па'дают на доро'жки. Ари'на собира'ет са'мые краси'вые. До'ма она' поло'жит их в то'лстую кни'гу, что'бы они' засо'хли ро'вными. Пото'м она' сде'лает из них карти'ну для ба'бушки. Под нога'ми ли'стья шурша'т, как бума'га. Шур, шур, шур! Э'то о'сень игра'ет свою' му'зыку.", [("листопа'д", "Листопа'д — э'то вре'мя, когда' с дере'вьев па'дают ли'стья.")]),
 ("магазин", "Ма'ма впервы'е отпра'вила Тиму'ра в магази'н одного'. Он взял спи'сок и де'ньги. Хлеб, молоко' и де'сять яи'ц. Тиму'р всё нашёл и встал в о'чередь. — С вас ты'сяча две'сти те'нге, — сказа'ла продавщи'ца. Тиму'р протяну'л де'ньги и получи'л сда'чу. Он аккура'тно пересчита'л её. Всё пра'вильно! Домо'й он шёл го'рдый и сча'стливый. Ма'ма похвали'ла его' и сказа'ла, что тепе'рь он настоя'щий помо'щник.", [("сда'ча", "Сда'ча — э'то де'ньги, кото'рые продаве'ц возвраща'ет обра'тно, е'сли ты дал бо'льше."), ("о'чередь", "О'чередь — э'то лю'ди, кото'рые стоя'т друг за дру'гом и ждут.")]),
 ("птицы", "Под кры'шей сара'я ла'сточки слепи'ли гнездо'. Они' носи'ли в клю'вах комо'чки гря'зи и трави'нки. Гнездо' получи'лось кре'пкое, похо'жее на ча'шку. Ско'ро в гнезде' запища'ли птенцы'. Ла'сточки це'лый день лови'ли мух и корми'ли малыше'й. Они' лета'ли так бы'стро, что за ни'ми тру'дно бы'ло уследи'ть. Птенцы' широко' раскрыва'ли жёлтые рты и проси'ли ещё. — Ско'лько же они' рабо'тают! — удиви'лась Айгу'ль. — Как настоя'щие роди'тели, — улыбну'лся де'душка.", [("птене'ц", "Птене'ц — э'то пти'чий малы'ш.")]),
 ("велосипед", "Але'му подари'ли велосипе'д. Снача'ла у него' бы'ли ма'ленькие боковы'е колёса. Ле'том па'па их снял. Але'м сел, оттолкну'лся и сра'зу упа'л. Он не запла'кал, а сно'ва взя'лся за руль. Па'па бежа'л ря'дом и держа'л седло'. А пото'м ти'хо отпусти'л. Але'м прое'хал це'лый круг сам! — Я е'ду! Я сам е'ду! — крича'л он.", [("седло'", "Седло' — э'то сиде'нье велосипе'да и'ли ло'шади.")]),
 ("снег", "Ди'ма пойма'л снежи'нку на ва'режку и посмотре'л на неё в лу'пу. Снежи'нка была' похо'жа на ма'ленькую звёздочку с шестью' луча'ми. — Па'па, все снежи'нки одина'ковые? — спроси'л Ди'ма. — Нет, — отве'тил па'па. — Говоря'т, что двух одина'ковых снежи'нок не быва'ет. Ди'ма пойма'л ещё одну'. И пра'вда, она' была' совсе'м друга'я! Ди'ма реши'л зарисова'ть ка'ждую снежи'нку в тетра'дку. Но они' та'яли сли'шком бы'стро!", [("лу'па", "Лу'па — э'то увеличи'тельное стекло'.")]),
 ("бабушка", "В суббо'ту ба'бушка гото'вила баурса'ки. Э'то пы'шные кусо'чки те'ста, кото'рые жа'рят в ма'сле. На ку'хне вку'сно па'хло. Айгу'ль помога'ла раска'тывать те'сто и ре'зать его' на квадра'тики. — Ба'бушка, а почему' они' таки'е пуза'тые? — В ма'сле те'сто раздува'ется, как ша'рик, — отве'тила ба'бушка. Горя'чие баурса'ки с ча'ем — са'мое вку'сное угоще'ние! Ба'бушка всегда' гото'вит их к прие'зду госте'й. Айгу'ль съе'ла пять штук и попроси'ла ещё.", [("баурса'к", "Баурса'к — э'то каза'хский пы'шный пирожо'к, жа'ренный в ма'сле."), ("угоще'ние", "Угоще'ние — э'то еда', кото'рой встреча'ют госте'й.")]),
 ("пруд", "Ве'чером на пруду' гро'мко ква'кают лягу'шки. Ари'на с па'пой подошли' побли'же. Лягу'шек бы'ло мно'го, и все пе'ли хо'ром. Одна' лягу'шка сиде'ла на листе' кувши'нки и раздува'ла щёки, как пузыри'. — Заче'м она' так де'лает? — спроси'ла Ари'на. — Так она' поёт гро'мче, — объясни'л па'па. — Пусть все слы'шат, кака'я она' краса'вица! Ари'на засмея'лась, а лягу'шка пры'гнула в во'ду. Плюх! То'лько круги' пошли' по воде'.", [("кувши'нка", "Кувши'нка — э'то цвето'к, кото'рый растёт пря'мо на воде'.")]),
 ("врач", "У Тиму'ра заболе'л зуб. Ма'ма повела' его' к стомато'логу. Тиму'р немно'го боя'лся. Но врач оказа'лся весёлым и до'брым. Он показа'л Тиму'ру все инструме'нты и да'же дал подержа'ть зе'ркальце. Лечи'ли зуб бы'стро и совсе'м не бо'льно. — Чи'сти зу'бы у'тром и ве'чером, — сказа'л врач. Тиму'р пообеща'л и получи'л в пода'рок накле'йку с аку'лой.", [("стомато'лог", "Стомато'лог — э'то врач, кото'рый ле'чит зу'бы.")]),
 ("муравьи", "Ерла'н сиде'л на ко'рточках и смотре'л на мураве'йник. Со'тни муравьёв бе'гали туда' и сюда'. Оди'н мураве'й тащи'л суху'ю ве'точку. Она' была' длинне'е его' в де'сять раз! — Како'й сила'ч! — удиви'лся Ерла'н. Де'душка рассказа'л, что мураве'й мо'жет подня'ть груз намно'го тяжеле'е себя'. Мураве'йник — э'то большо'й дом, где ка'ждый за'нят свои'м де'лом. Ерла'н положи'л ря'дом кро'шку хле'ба. Муравьи' сра'зу её нашли' и потащи'ли домо'й. — Как у нас в семье'! — улыбну'лся Ерла'н.", [("мураве'йник", "Мураве'йник — э'то дом муравьёв, похо'жий на ку'чу иго'лок."), ("сила'ч", "Сила'ч — э'то о'чень си'льный челове'к и'ли зверь.")]),
 ("дождь", "Ди'ма наде'л рези'новые сапоги' и пошёл гуля'ть под дождём. Ма'ма шла ря'дом под больши'м зонто'м. Он пры'гал по всем лу'жам подря'д. Шлёп! Бры'зги лете'ли во все сто'роны. Вдруг Ди'ма уви'дел огро'мную лу'жу, широ'кую, как о'зеро. Он разбежа'лся и пры'гнул. Но лу'жа оказа'лась глу'бже, чем сапоги'! — Ну что, моря'к, — засмея'лась ма'ма, — пора' суши'ться! До'ма Ди'ма вы'лил из сапо'г це'лую лу'жу.", [("бры'зги", "Бры'зги — э'то ме'лкие ка'пли, кото'рые разлета'ются в сто'роны.")]),
 ("следы", "По'сле снегопа'да па'па и Але'м пошли' на лы'жах в лес. На бе'лом снегу' бы'ло мно'го следо'в. Вот цепо'чка ма'леньких ла'пок, э'то пробежа'ла мы'шка. А вот дли'нные следы', тут пры'гал за'яц. — А э'ти чьи? — спроси'л Але'м. Следы' шли ро'вно, оди'н за други'м, как по ни'точке. — Э'то лиса', — отве'тил па'па. — Она' ста'вит ла'пы то'чно в одну' ли'нию.", [("снегопа'д", "Снегопа'д — э'то когда' с не'ба па'дает мно'го сне'га.")]),
 ("праздник", "У Ами'ны день рожде'ния. Ей испо'лнилось во'семь лет. В го'сти пришли' её подру'ги. Они' принесли' пода'рки и возду'шные ша'рики. Ма'ма испекла' большо'й торт с клубни'кой и поста'вила на него' во'семь свече'й. — Загада'й жела'ние! — сказа'ла ба'бушка. Ами'на зажму'рилась, глубоко' вдохну'ла и заду'ла все све'чи сра'зу. Все захло'пали в ладо'ши. А что она' загада'ла, никому' не ска'жет. Ведь е'сли рассказа'ть, жела'ние не сбу'дется.", [("зажму'рилась", "Зажму'рилась — зна'чит кре'пко закры'ла глаза'.")]),
 ("змей", "В ве'треный день Ерла'н и па'па запуска'ли возду'шного змея'. Змей был кра'сный, с дли'нным хвосто'м. Па'па побежа'л, ве'тер подхвати'л змея', и он взмыл в не'бо. — Держи' кре'пче! — кри'кнул па'па и отда'л Ерла'ну верёвку. Змей рва'лся вверх, как живо'й. Ерла'н ра'достно смея'лся. Высоко' над сте'пью ве'тер игра'л с его' кра'сным драко'ном.", [("возду'шный змей", "Возду'шный змей — э'то лёгкая игру'шка на верёвке, кото'рую поднима'ет ве'тер."), ("взмыл", "Взмыл — зна'чит бы'стро подня'лся вверх.")]),
 ("огород", "Весно'й Айгу'ль с де'душкой посади'ли на огоро'де горо'х. Ка'ждое у'тро де'вочка бе'гала смотре'ть, не появи'лись ли ростки'. Наконе'ц из земли' показа'лись зелёные пе'тельки. Ско'ро они' ста'ли расти' и цепля'ться за па'лочки. В ию'ле на ку'стиках вы'росли стручки'. Айгу'ль откры'ла оди'н, а там ро'вные зелёные горо'шины. — Как бу'сы! — обра'довалась она'. Горо'х оказа'лся сла'дким и хрустя'щим. Айгу'ль подели'лась им с де'душкой.", [("стручо'к", "Стручо'к — э'то зелёный футля'р, в кото'ром расту'т горо'шины.")]),
 ("котята", "У ко'шки Му'рки родили'сь котя'та. Их пя'теро. Три се'рых, оди'н ры'жий и оди'н чёрный. Снача'ла они' бы'ли слепы'е и то'лько пища'ли. Му'рка корми'ла их молоко'м и выли'зывала языко'м. Че'рез неде'лю у них откры'лись глаза'. Тепе'рь котя'та по'лзают по коро'бке и пыта'ются пойма'ть хвост ма'мы. Ди'ма приду'мывает им имена'. — Ры'жего назовём Апельси'н! — предлага'ет он. — А чёрного назовём Уголёк! Ма'ма смеётся и соглаша'ется.", [("слепо'й", "Слепо'й — зна'чит тот, кто ничего' не ви'дит.")]),
 ("каток", "Зимо'й во дворе' сде'лали като'к. Ари'на впервы'е вста'ла на коньки'. Но'ги разъезжа'лись в ра'зные сто'роны, и она' то и де'ло па'дала. — Не бо'йся, держи'сь за меня'! — сказа'л ста'рший брат Тиму'р. Он взял сестру' за ру'ку, и они' ме'дленно пое'хали по кру'гу. К ве'черу Ари'на уже' ката'лась сама'. Щёки у неё горе'ли, а глаза' сия'ли.", [("разъезжа'лись", "Разъезжа'лись — зна'чит скользи'ли в ра'зные сто'роны.")]),
 ("луна", "Ве'чером Але'м заме'тил, что Луна' похо'жа на кусо'к ды'ни. Она' висе'ла над до'мом, то'нкая и жёлтая. А неде'лю наза'д она' была' кру'глая, как таре'лка. — Ма'ма, почему' Луна' уменьша'ется? — спроси'л он. — Луна' сама' не све'тит, — отве'тила ма'ма. — Её освеща'ет Со'лнце. Мы ви'дим то'лько ту часть, на кото'рую па'дает свет. Ско'ро Луна' сно'ва ста'нет кру'глой. Э'то бу'дет полнолу'ние. Тогда' но'чью на у'лице светло', почти' как днём.", [("освеща'ет", "Освеща'ет — зна'чит направля'ет на неё свет.")]),
 ("автобус", "Ка'ждое у'тро Ерла'н е'дет в шко'лу на авто'бусе. Он всегда' сади'тся у окна'. За окно'м мелька'ют дома', магази'ны и дере'вья. Одна'жды в авто'бус вошла' пожила'я же'нщина с тяжёлой су'мкой. Все места' бы'ли за'няты. Ерла'н сра'зу встал и уступи'л ей ме'сто. — Спаси'бо, сыно'к! — сказа'ла она'. — Како'й ты воспи'танный ма'льчик. Ерла'ну ста'ло тепло' на душе'.", [("пожила'я", "Пожила'я — зна'чит немолода'я, в во'зрасте."), ("уступи'л", "Уступи'л ме'сто — зна'чит встал и дал сесть друго'му.")]),
 ("подсолнух", "На краю' по'ля вы'рос подсо'лнух. Он вы'ше Тиму'ра и да'же вы'ше па'пы! У него' больша'я жёлтая голова'. Пока' подсо'лнух молодо'й, она' повора'чивается за со'лнцем. У'тром смо'трит на восто'к, а ве'чером на за'пад. — Он следи'т за со'лнцем! — удиви'лся Тиму'р. О'сенью в середи'не цветка' созре'ют се'мечки. Их о'чень лю'бят пти'цы. А ещё из них де'лают подсо'лнечное ма'сло. Тиму'р реши'л на бу'дущий год посади'ть це'лый ряд подсо'лнухов.", [("подсо'лнух", "Подсо'лнух — э'то высо'кий цвето'к с больши'ми се'мечками.")]),
 ("шахматы", "Де'душка научи'л Але'ма игра'ть в ша'хматы. Але'м запо'мнил, как хо'дит ка'ждая фигу'ра. Конь хо'дит хи'тро, угло'м, а слон то'лько наискосо'к. Они' сыгра'ли пе'рвую па'ртию, и де'душка вы'играл. Пото'м втору'ю, и опя'ть вы'играл де'душка. — Не расстра'ивайся, — сказа'л он. — Я то'же снача'ла прои'грывал. Але'м сосредото'чился и в тре'тьей па'ртии поста'вил де'душке мат!", [("па'ртия", "Па'ртия — э'то одна' игра' от нача'ла до конца'."), ("наискосо'к", "Наискосо'к — зна'чит не пря'мо, а на'искось, по диагона'ли.")]),
 ("пасека", "Ле'том Ами'на с па'пой е'здили на па'секу. Там стоя'ли деся'тки у'льев. Пчелово'д дал им защи'тные се'тки на лицо'. Вокру'г гуде'ли пчёлы, но никого' не ужа'лили. — Пчёлы не тро'гают споко'йных люде'й, — объясни'л пчелово'д. Пото'м он угости'л госте'й све'жим мёдом. Мёд был прозра'чный, золото'й и па'хнул цвета'ми. Ами'на съе'ла це'лую ло'жку и зажму'рилась от удово'льствия. — Э'то са'мый вку'сный мёд на све'те! — сказа'ла она'.", [("па'сека", "Па'сека — э'то ме'сто, где стоя'т у'льи с пчёлами."), ("у'лей", "У'лей — э'то до'мик для пчёл.")]),
 ("бассейн", "Тиму'р хо'дит в бассе'йн два ра'за в неде'лю. Снача'ла он пла'вал то'лько с доско'й. Тепе'рь он уме'ет пла'вать кро'лем и ныря'ть. Сего'дня тре'нер устро'ил соревнова'ние. — На старт! Внима'ние! Марш! Тиму'р пры'гнул в во'ду и поплы'л что есть сил. Он приплы'л вторы'м, и тре'нер пожа'л ему' ру'ку. — Ско'ро бу'дешь пе'рвым! — сказа'л он.", [("кроль", "Кроль — э'то са'мый бы'стрый спо'соб пла'вания.")]),
 ("утро", "Буди'льник звене'л уже' тре'тий раз, а Ди'ма всё спал. — Ди'ма, встава'й, опозда'ешь! — звала' ма'ма. Ди'ма вскочи'л, бы'стро оде'лся и побежа'л на ку'хню. Тут он уви'дел, что за окно'м ещё темно', а на календаре' суббо'та! Ма'ма засмея'лась. — Э'то я пошути'ла. Иди' досыпа'й, со'ня! Ди'ма поверну'лся на друго'й бок, но спать уже' не хоте'лось. Он сел ря'дом с ма'мой, и они' вме'сте пи'ли чай с блина'ми.", [("со'ня", "Со'ня — так ла'сково называ'ют того', кто лю'бит до'лго спать.")]),
]

# L7 — 3 класс: 80–110 слов, сложносочинённые предложения, небольшой сюжет.
L7 = [
 ("ракета", "В суббо'ту па'па и Тиму'р де'лали раке'ту из пла'стиковой буты'лки. Они' прикле'или к ней карто'нные кры'лья, а све'рху наде'ли о'стрый колпа'к. Пото'м па'па доба'вил в буты'лку немно'го воды' и подключи'л насо'с. Ребя'та со всего' двора' собрали'сь посмотре'ть на за'пуск. Тиму'р на'чал кача'ть насо'с, и давле'ние внутри' росло'. — Три, два, оди'н, пуск! — закрича'ли все хо'ром. Раке'та с шу'мом вы'рвалась из подста'вки и взлете'ла вы'ше до'ма. Вода' бры'знула во все сто'роны, и пе'рвый ряд зри'телей промо'к до ни'тки. Но никто' не оби'делся. Все проси'ли запусти'ть ещё раз!", [("насо'с", "Насо'с — э'то прибо'р, кото'рый нака'чивает во'здух."), ("давле'ние", "Давле'ние — э'то си'ла, с кото'рой во'здух да'вит изнутри'."), ("промо'к до ни'тки", "Промо'к до ни'тки — зна'чит промо'к весь, наскво'зь.")]),
 ("собака", "Ве'чером Ами'на уви'дела у подъе'зда ма'ленькую ры'жую соба'ку. Соба'ка дрожа'ла от хо'лода и жа'лобно скули'ла. На ше'е у неё был оше'йник, а зна'чит, у соба'ки есть хозя'ин. Ами'на принесла' ей ми'ску с водо'й, а па'па сфотографи'ровал соба'ку и написа'л объявле'ние. Его' пове'сили на двери' подъе'зда и в интерне'те. Всю ночь соба'ка спала' у них в прихо'жей на ста'ром пле'де. А у'тром позвони'ла де'вочка из сосе'днего двора'. Она' прибежа'ла и запла'кала от ра'дости. — Ло'ла, ты нашла'сь! Соба'ка ра'достно завиля'ла хвосто'м и лизну'ла её в нос.", [("скули'ла", "Скули'ла — зна'чит жа'лобно и то'нко подвыва'ла."), ("объявле'ние", "Объявле'ние — э'то запи'ска для всех, в кото'рой сообща'ют ва'жную но'вость.")]),
 ("поход", "Ле'том па'па, Ерла'н и его' друг Ди'ма пошли' в похо'д. Они' шли це'лый день по бе'регу реки', а к ве'черу поста'вили пала'тку на поля'не. Ма'льчики собира'ли сухи'е ве'тки, а па'па развёл костёр. В котелке' свари'ли ка'шу с тушёнкой. Она' па'хла ды'мом и каза'лась вкусне'е всего' на све'те. Когда' стемне'ло, над голово'й зажгли'сь звёзды. Их бы'ло так мно'го, как никогда' не быва'ет в го'роде. — Смотри'те, спу'тник! — кри'кнул Ди'ма. По не'бу ме'дленно ползла' я'ркая то'чка. Ма'льчики до'лго смотре'ли на неё и мечта'ли о ко'смосе.", [("котело'к", "Котело'к — э'то похо'дная кастрю'ля, в кото'рой ва'рят еду' на костре'."), ("спу'тник", "Спу'тник — э'то аппара'т, кото'рый лета'ет вокру'г Земли'.")]),
 ("метель", "Зимо'й Але'м с ма'мой возвраща'лись из госте'й. Вдруг начала'сь мете'ль. Снег лете'л в лицо', и в двух шага'х ничего' нельзя' бы'ло разгляде'ть. Ма'ма взяла' Але'ма за ру'ку, и они' пошли' вдоль забо'ра. Але'м стара'лся не отстава'ть. Но'ги вя'зли в сугро'бах, а ве'тер выл, как волк. Наконе'ц впереди' показа'лся жёлтый огонёк. Э'то свети'лось окно' их до'ма! Па'па уже' ждал у подъе'зда с фонарём. До'ма их напои'ли горя'чим ча'ем, и Але'м ско'ро согре'лся. — Мы с тобо'й победи'ли мете'ль! — сказа'ла ма'ма, и Але'м го'рдо кивну'л.", [("мете'ль", "Мете'ль — э'то си'льный ве'тер со сне'гом."), ("вя'зли", "Вя'зли — зна'чит прова'ливались и застрева'ли.")]),
 ("робот", "Ди'ма собра'л из констру'ктора ро'бота. У него' бы'ли колёса, мото'р и да'тчик, кото'рый замеча'ет препя'тствия. Ди'ма написа'л для ро'бота програ'мму. Ро'бот до'лжен был прое'хать по коридо'ру, поверну'ть на ку'хню и привезти' ма'ме конфе'ту. Но всё пошло' не так. Ро'бот бо'дро пое'хал вперёд, зате'м разверну'лся и уе'хал в ва'нную. Там он заблуди'лся ме'жду стира'льной маши'ной и корзи'ной для белья'. Ди'ма до'лго иска'л оши'бку в програ'мме и наконе'ц нашёл её. Он перепу'тал пра'во и ле'во! Со второ'й попы'тки ро'бот привёз ма'ме конфе'ту, а ма'ма торже'ственно назвала' Ди'му гла'вным инжене'ром.", [("да'тчик", "Да'тчик — э'то прибо'р, кото'рый чу'вствует свет, звук и'ли прегра'ду."), ("препя'тствие", "Препя'тствие — э'то то, что меша'ет пройти' и'ли прое'хать.")]),
 ("футбол", "В на'шем дворе' устро'или турни'р по футбо'лу. Игра'ли четы'ре кома'нды из сосе'дних домо'в. На'ша кома'нда называ'лась Мо'лния, а у кома'нды из до'ма напро'тив бы'ли кра'сные футбо'лки. Пе'рвый тайм мы прои'грывали, и все приуны'ли. В переры'ве капита'н Ерла'н собра'л нас в круг. — Мы игра'ем ка'ждый сам за себя', а на'до пасова'ть! — сказа'л он. Во второ'м та'йме мы ста'ли игра'ть вме'сте, и де'ло пошло'. Снача'ла Тиму'р сравня'л счёт, а пото'м Ерла'н заби'л побе'дный гол. Ма'мы на скаме'йке крича'ли и хло'пали гро'мче всех.", [("тайм", "Тайм — э'то полови'на футбо'льного ма'тча."), ("приуны'ли", "Приуны'ли — зна'чит загрусти'ли."), ("пасова'ть", "Пасова'ть — зна'чит передава'ть мяч друго'му игроку'.")]),
 ("рыбалка", "Де'душка взял Тиму'ра на рыба'лку. Они' сиде'ли на берегу' о'зера с са'мого рассве'та. У де'душки клева'ло ка'ждые пять мину'т, а поплаво'к Тиму'ра не шевели'лся. Тиму'р уже' на'чал скуча'ть, но вдруг у'дочка согну'лась дуго'й. — Тащи', не торопи'сь! — закрича'л де'душка. Тиму'р тяну'л из после'дних сил. Вода' забурли'ла, и из неё показа'лся ста'рый рези'новый сапо'г! Де'душка так смея'лся, что чуть не упа'л в во'ду. — Ничего', — сказа'л он. — Тепе'рь у нас есть сапо'г, оста'лось пойма'ть второ'й! А че'рез час Тиму'р пойма'л настоя'щего о'куня. До'ма ба'бушка пожа'рила его' на у'жин, а сапо'г пове'сили в сара'е на па'мять.", [("рассве'т", "Рассве'т — э'то ра'ннее у'тро, когда' то'лько встаёт со'лнце."), ("клева'ть", "Клева'ть — зна'чит хвата'ть нажи'вку на крючке'. Так говоря'т о ры'бе."), ("о'кунь", "О'кунь — э'то полоса'тая речна'я ры'ба.")]),
 ("дракон", "В далёких гора'х жил ма'ленький драко'н И'скорка. Все драко'ны уме'ли дыша'ть огнём, а И'скорка выдыха'л то'лько мы'льные пузыри'. Ста'ршие драко'ны смея'лись над ним, и ему' бы'ло о'чень оби'дно. Одна'жды в гора'х случи'лся пожа'р. Суха'я трава' вспы'хнула, и ого'нь побежа'л к дере'вне. Драко'ны растеря'лись, ведь огнём ого'нь не поту'шишь. Тогда' И'скорка глубоко' вдохну'л и вы'пустил ты'сячи пузыре'й. Они' ло'пались над пла'менем, как ма'ленькие ту'чки, и пожа'р пога'с. С тех пор никто' не смеётся над И'скоркой, а в дере'вне его' называ'ют спаси'телем.", [("пла'мя", "Пла'мя — э'то языки' огня'."), ("растеря'лись", "Растеря'лись — зна'чит не зна'ли, что де'лать.")]),
 ("попугай", "У Айгу'ль живёт зелёный попуга'й Ке'ша. Он уме'ет говори'ть не'сколько слов и о'чень лю'бит подража'ть зву'кам. Он мяу'кает, как ко'шка, и скрипи'т, как дверь. Одна'жды ма'ма гото'вила обе'д, и вдруг зазвони'л телефо'н. Ма'ма бро'силась в ко'мнату, но телефо'н молча'л на столе'. Че'рез мину'ту звоно'к повтори'лся. Ма'ма опя'ть прибежа'ла, и опя'ть телефо'н молча'л. Тогда' Айгу'ль заме'тила, что Ке'ша лука'во смо'трит на них и уже' гото'вится к но'вому звонку'. — Так э'то ты звони'шь! — засмея'лась ма'ма. А Ке'ша ва'жно распуши'л пе'рья и сказа'л свои' люби'мые слова': — Ке'ша хоро'ший! Ма'ма дала' ему' кусо'чек я'блока за тала'нт.", [("подража'ть", "Подража'ть — зна'чит повторя'ть за други'м."), ("лука'во", "Лука'во — зна'чит хи'тро и с усме'шкой.")]),
 ("яблоки", "Ка'ждую о'сень Але'м е'здит к де'душке в Алматы'. У де'душки в саду' растёт ста'рая я'блоня со'рта апо'рт. Её я'блоки таки'е больши'е, что одно' с трудо'м помеща'ется в двух ладо'нях. Але'м забира'ется на ле'стницу, а де'душка де'ржит её внизу'. Са'мые высо'кие я'блоки они' снима'ют специа'льной па'лкой с корзи'нкой на конце'. Пото'м я'блоки аккура'тно скла'дывают в я'щики. До'ма ба'бушка ва'рит из них варе'нье, а са'мые краси'вые я'блоки оставля'ет на зи'му. — Дед, а почему' го'род называ'ется Алматы'? — спра'шивает Але'м. — Потому' что сло'во алма' означа'ет я'блоко, — отвеча'ет де'душка. — Здесь я'блони расту'т с о'чень да'вних времён.", [("апо'рт", "Апо'рт — э'то сорт огро'мных кра'сных я'блок."), ("сорт", "Сорт — э'то вид расте'ния с осо'быми плода'ми.")]),
 ("дружба", "Ди'ма и Тиму'р дружи'ли с пе'рвого кла'сса. Но одна'жды они' поссо'рились. Ди'ма взял мяч Тиму'ра без спро'са и потеря'л его'. Тиму'р оби'делся и переста'л с ним разгова'ривать. Це'лую неде'лю они' сиде'ли за ра'зными па'ртами и не смотре'ли друг на дру'га. Ди'ме бы'ло гру'стно, а Тиму'ру ску'чно. В суббо'ту Ди'ма разби'л свою' копи'лку и купи'л но'вый мяч. Он пришёл к Тиму'ру и протяну'л ему' мяч. — Прости' меня', я был непра'в. Тиму'р улыбну'лся и пожа'л ему' ру'ку. А но'вый мяч они' тут же опро'бовали во дворе'.", [("без спро'са", "Без спро'са — зна'чит не спроси'в разреше'ния."), ("опро'бовали", "Опро'бовали — зна'чит попро'бовали в де'ле.")]),
 ("жираф", "В зоопа'рке Ари'на бо'льше всего' хоте'ла уви'деть жира'фа. И вот он стои'т за высо'кой огра'дой и жуёт ли'стья с верху'шки де'рева. Ше'я у него' така'я дли'нная, что голова' почти' каса'ется кры'ши. Он вы'ше, чем два па'пы, е'сли поста'вить их друг на дру'га! Смотри'тель дал Ари'не ве'тку с ли'стьями, и жира'ф наклони'лся к ней. Он вы'сунул дли'нный тёмный язы'к и ло'вко сорва'л ли'стья. — Како'й у него' язы'к! — а'хнула Ари'на. — Почти' полме'тра, — объясни'л смотри'тель. — Им жира'ф достаёт са'мые со'чные ли'стья на са'мом верху'.", [("огра'да", "Огра'да — э'то забо'р."), ("смотри'тель", "Смотри'тель — э'то челове'к, кото'рый уха'живает за живо'тными в зоопа'рке.")]),
 ("самолёт", "Тиму'р с па'пой собира'ли моде'ль самолёта це'лых две неде'ли. Они' вы'резали кры'лья из то'нких деревя'нных ре'ек и обтя'гивали их бума'гой. Тиму'р покра'сил самолёт в си'ний цвет и нарисова'л на кры'льях звёзды. Наконе'ц моде'ль была' гото'ва. В воскресе'нье они' пое'хали в широ'кое по'ле за го'родом. Па'па закрути'л рези'новый мото'р, и Тиму'р запусти'л самолёт. Он пролете'л над траво'й, сде'лал круг и мя'гко приземли'лся. Па'па и Тиму'р побежа'ли к нему' по высо'кой траве'. — Ура'! Он лета'ет! — закрича'л Тиму'р. Пото'м они' запуска'ли его' сно'ва и сно'ва, пока' не ста'ло темно'. А на сле'дующей неде'ле они' реши'ли постро'ить вертолёт.", [("моде'ль", "Моде'ль — э'то ма'ленькая ко'пия настоя'щей маши'ны и'ли самолёта."), ("приземли'лся", "Приземли'лся — зна'чит опусти'лся на зе'млю по'сле полёта.")]),
 ("бурабай", "Ле'том на'ша семья' е'здила на о'зеро Бураба'й. Э'то удиви'тельное ме'сто, где посреди' степи' вдруг поднима'ются го'ры, покры'тые со'снами. Вода' в о'зере чи'стая и прохла'дная, а на берегу' лежа'т гла'дкие ка'мни. Ди'ма и Ерла'н купа'лись, стро'или за'мки из песка' и иска'ли интере'сные ка'мешки. Ерла'н нашёл ка'мень, похо'жий на се'рдце, и подари'л его' ма'ме. Ве'чером у костра' па'па рассказа'л леге'нду. Говоря'т, что когда' Бог раздава'л зе'млю, каза'хам доста'лась то'лько ро'вная степь. Тогда' Бог взял горсть сокро'вищ и бро'сил её посреди' степи'. Так и появи'лись э'ти го'ры, леса' и озёра. Пото'м они' до'лго смотре'ли на звёзды над тёмной водо'й.", [("леге'нда", "Леге'нда — э'то стари'нный расска'з о чу'де."), ("сокро'вища", "Сокро'вища — э'то о'чень це'нные ве'щи.")]),
 ("конь", "У де'душки Але'ма в ау'ле живёт конь по кли'чке Тулпа'р. Он высо'кий, гнедо'й, с бе'лым пятно'м на лбу. Ка'ждое у'тро де'душка и Але'м чи'стят его' щёткой, расчёсывают гри'ву и даю'т ему' овса'. Конь стои'т споко'йно и то'лько иногда' пома'хивает хвосто'м. Тулпа'р лю'бит морко'вку и всегда' тя'нется к карма'нам Але'ма. Одна'жды де'душка посади'л вну'ка в седло' и повёл коня' по двору'. Але'м снача'ла кре'пко держа'лся за гри'ву, а пото'м вы'прямился и улыбну'лся. — Ты прирождённый нае'здник! — сказа'л де'душка. — Как твой пра'дед. Он был лу'чшим нае'здником во всём ау'ле. Тулпа'р фы'ркнул, бу'дто то'же согласи'лся.", [("гнедо'й", "Гнедо'й — зна'чит кори'чневый, с чёрной гри'вой и хвосто'м."), ("гри'ва", "Гри'ва — э'то дли'нные во'лосы на ше'е ло'шади."), ("нае'здник", "Нае'здник — э'то тот, кто е'дет верхо'м на ло'шади.")]),
 ("письмо", "Ами'на реши'ла написа'ть ба'бушке настоя'щее письмо'. Не сообще'ние в телефо'не, а письмо' на бума'ге. Она' взяла' краси'вый лист и написа'ла, как прошла' её неде'ля. Рассказа'ла про пятёрку по матема'тике, про но'вую подру'гу и про котёнка во дворе'. В конце' она' нарисова'ла ба'бушкин дом и со'лнце над ним. Пото'м Ами'на положи'ла письмо' в конве'рт, накле'ила ма'рку и опусти'ла его' в почто'вый я'щик. Че'рез неде'лю позвони'ла ба'бушка. — Я прочита'ла твоё письмо' пять раз! — сказа'ла она'. — И пове'сила твой рису'нок на са'мое ви'дное ме'сто.", [("конве'рт", "Конве'рт — э'то бума'жный паке'т для письма'."), ("ма'рка", "Ма'рка — э'то ма'ленькая накле'йка, кото'рая пока'зывает, что за письмо' заплати'ли.")]),
 ("пингвины", "Ве'чером Ерла'н смотре'л фильм про импера'торских пингви'нов. Они' живу'т в Антаркти'де, где зимо'й быва'ет сильне'е пяти'десяти гра'дусов моро'за. Ма'ма пингви'на откла'дывает яйцо' и ухо'дит в мо'ре за едо'й. А па'па це'лых два ме'сяца де'ржит яйцо' на ла'пах и согрева'ет его' свои'м живото'м. Всё э'то вре'мя он ничего' не ест! Па'пы стоя'т, те'сно прижа'вшись друг к дру'гу, что'бы не замёрзнуть. — Вот э'то па'па! — сказа'л Ерла'н и посмотре'л на своего' отца'. Па'па засмея'лся. — Я бы то'же смог. Но то'лько е'сли ты бу'дешь корми'ть меня' пирожка'ми.", [("Антаркти'да", "Антаркти'да — э'то ледяно'й контине'нт на ю'ге Земли'."), ("импера'торский", "Импера'торский пингви'н — э'то са'мый большо'й пингви'н на све'те.")]),
 ("воробей", "По'сле си'льного ве'тра Ди'ма нашёл во дворе' воробьи'ного птенца'. Он ещё пло'хо лета'л и пря'тался в траве'. Ди'ма хоте'л забра'ть его' домо'й, но ма'ма останови'ла его'. — Подожди'. Роди'тели наверняка' ря'дом и следя'т за ним, — сказа'ла она'. Они' отошли' в сто'рону и спря'тались за скаме'йкой. И пра'вда, вско'ре прилете'л воробе'й с червячко'м в клю'ве. Он покорми'л птенца' и гро'мко зачири'кал, бу'дто руга'л его'. Че'рез не'сколько дней птене'ц уже' ло'вко порха'л с ве'тки на ве'тку. Ди'ма был рад, что не унёс его' домо'й.", [("наверняка'", "Наверняка' — зна'чит то'чно, без сомне'ния."), ("порха'л", "Порха'л — зна'чит легко' перелета'л с ме'ста на ме'сто.")]),
 ("изобретатель", "Ерла'н лю'бит изобрета'ть. На э'тот раз он реши'л постро'ить маши'ну, кото'рая сама' бу'дет причёсывать кота'. Он прикрепи'л ста'рую расчёску к игру'шечной маши'нке с мото'ром и включи'л её. Маши'нка зажужжа'ла и поползла' к коту' Пушку'. Пушо'к снача'ла удивлённо посмотре'л на неё, пото'м вы'гнул спи'ну и зашипе'л. А пото'м пры'гнул пря'мо на шкаф! Маши'нка дое'хала до дива'на, упёрлась в него' и ещё до'лго причёсывала оби'вку. — Ну, хотя' бы дива'н тепе'рь краси'вый, — вздохну'ла ма'ма. А Ерла'н сел приду'мывать но'вое изобрете'ние. На э'тот раз маши'ну для мытья' посу'ды. Ма'ма на вся'кий слу'чай спря'тала все таре'лки.", [("изобрета'ть", "Изобрета'ть — зна'чит приду'мывать но'вые маши'ны и ве'щи."), ("оби'вка", "Оби'вка — э'то ткань, кото'рой обтя'нут дива'н.")]),
 ("метро", "В Алматы' Тиму'р впервы'е спусти'лся в метро'. Эскала'тор был тако'й дли'нный, что каза'лось, бу'дто он везёт их к са'мому це'нтру Земли'. Па'па показа'л, что на эскала'торе на'до стоя'ть спра'ва и держа'ться за по'ручень. Внизу' была' краси'вая ста'нция с мозаи'кой на стена'х. Подъе'хал по'езд, две'ри с шу'мом раскры'лись, и они' вошли' в ваго'н. — Па'па, а как машини'ст ви'дит доро'гу в темноте'? — спроси'л Тиму'р. — У по'езда есть фа'ры, а ещё ему' помога'ют светофо'ры, — отве'тил па'па. Тиму'р реши'л, что, когда' вы'растет, ста'нет машини'стом метро'.", [("эскала'тор", "Эскала'тор — э'то дви'жущаяся ле'стница."), ("по'ручень", "По'ручень — э'то пери'ла, за кото'рые де'ржатся руко'й."), ("машини'ст", "Машини'ст — э'то води'тель по'езда.")]),
 ("лыжи", "В шко'ле устро'или лы'жные соревнова'ния. Ами'на волнова'лась, ведь она' вста'ла на лы'жи то'лько э'той зимо'й. На ста'рте она' отста'ла от всех, но не сдала'сь. Снег скрипе'л под лы'жами, а щёки щипа'л моро'з. Она' ста'ла дыша'ть ро'вно и отта'лкиваться па'лками, как учи'л тре'нер. Постепе'нно Ами'на догнала' одну' де'вочку, пото'м другу'ю. На после'днем подъёме мно'гие устава'ли и шли пешко'м, а Ами'на поднима'лась ёлочкой. Она' пришла' к фи'нишу тре'тьей! Ма'ма и па'па, кото'рые жда'ли у фи'ниша, бро'сились её обнима'ть. — Ты молоде'ц, — сказа'л тре'нер. — Гла'вное, ты не сдала'сь. До'ма Ами'на пове'сила свою' пе'рвую меда'ль над крова'тью.", [("ёлочкой", "Поднима'ться ёлочкой — зна'чит ста'вить лы'жи носка'ми в сто'роны, и след похо'ж на ёлку."), ("фи'ниш", "Фи'ниш — э'то коне'ц диста'нции, где зака'нчивается го'нка.")]),
 ("мороженое", "Был са'мый жа'ркий день ле'та. Асфа'льт пла'вился от жары', а соба'ки пря'тались в тени'. Ди'ма и его' мла'дшая сестра' Ари'на купи'ли по по'рции моро'женого. Ди'ма вы'брал шокола'дное, а Ари'на клубни'чное. Продаве'ц посы'пал моро'женое цветно'й посы'пкой. Пока' они' шли домо'й, моро'женое на'чало та'ять. Сла'дкие ка'пли текли' по рука'м и па'дали на тротуа'р. Ди'ма ел бы'стро, а Ари'на ме'дленно, что'бы подо'льше растяну'ть удово'льствие. В ито'ге у Ди'мы оста'лся пусто'й стака'нчик, а у Ари'ны лу'жица на ладо'ни. — Сле'дующее бу'дем есть до'ма, в холоди'льнике! — пошути'л Ди'ма. Ари'на облиза'ла ладо'нь и засмея'лась. — Зато' я его' до'льше е'ла!", [("асфа'льт", "Асфа'льт — э'то твёрдое чёрное покры'тие доро'г."), ("по'рция", "По'рция — э'то часть еды' для одного' челове'ка.")]),
 ("сова", "Ле'том на да'че Але'м просну'лся среди' но'чи от стра'нного зву'ка. — Угу', угу'! — доноси'лось из са'да. Але'м разбуди'л па'пу, и они' вы'шли на крыльцо' с фона'риком. На ста'рой берёзе сиде'ла больша'я сова' и смотре'ла на них кру'глыми жёлтыми глаза'ми. Она' поверну'ла го'лову почти' наза'д, и Але'м а'хнул. Ему' показа'лось, что сова' сейча'с откру'тит себе' го'лову. — Со'вы мо'гут повора'чивать го'лову о'чень далеко', — шёпотом объясни'л па'па. — Зато' они' не мо'гут дви'гать глаза'ми. Сова' у'хнула ещё раз, бесшу'мно взмахну'ла кры'льями и улете'ла в темноту'. Але'м ещё до'лго не мог усну'ть и слу'шал ночно'й сад.", [("крыльцо'", "Крыльцо' — э'то ступе'ньки и площа'дка пе'ред две'рью до'ма."), ("бесшу'мно", "Бесшу'мно — зна'чит совсе'м ти'хо.")]),
 ("барс", "В па'рке объяви'ли ко'нкурс сне'жных фигу'р. Ерла'н, Ами'на и па'па реши'ли вы'лепить сне'жного ба'рса. Па'па ката'л огро'мные ко'мья, Ерла'н лепи'л ла'пы, а Ами'на дли'нный пуши'стый хвост. Пото'м они' тща'тельно вы'резали мо'рду ло'жкой. Барс получи'лся как живо'й, то'лько бе'лый. Ами'на вста'вила ему' вме'сто глаз два зелёных ка'мешка. Ря'дом стоя'ли сне'жная кре'пость, огро'мный кит и да'же раке'та. Жюри' до'лго ходи'ло ме'жду фигу'рами и совеща'лось. Пе'рвое ме'сто доста'лось раке'те, а ба'рсу второ'е. Но Ерла'н всё равно' был сча'стлив. Ведь их барс улыба'лся, а э'то ре'дкость для сне'жных ба'рсов! Его' сфотографи'ровали и показа'ли в городски'х новостя'х.", [("жюри'", "Жюри' — э'то лю'ди, кото'рые выбира'ют победи'телей ко'нкурса."), ("тща'тельно", "Тща'тельно — зна'чит о'чень стара'тельно и аккура'тно.")]),
 ("библиотека", "Ди'ма записа'лся в библиоте'ку. Библиоте'карь показа'ла ему' по'лки с де'тскими кни'гами. Их бы'ло так мно'го, что Ди'ма растеря'лся. Там бы'ли кни'ги о живо'тных, о ры'царях, о маши'нах и о далёких стра'нах. — Что ты лю'бишь? — спроси'ла она'. — Про ко'смос и про приключе'ния, — отве'тил Ди'ма. Библиоте'карь улыбну'лась и принесла' то'лстую кни'гу о путеше'ствии на Марс. Ди'ма чита'л её це'лую неде'лю. Он чита'л до'ма, в авто'бусе и да'же под одея'лом с фона'риком. Когда' кни'га ко'нчилась, он сра'зу побежа'л за но'вой. — Ты так ско'ро прочита'ешь всю библиоте'ку! — пошути'ла библиоте'карь. — Ничего', — отве'тил Ди'ма. — Зна'чит, запишу'сь ещё в одну'!", [("библиоте'карь", "Библиоте'карь — э'то челове'к, кото'рый рабо'тает в библиоте'ке и выдаёт кни'ги."), ("приключе'ния", "Приключе'ния — э'то интере'сные и опа'сные собы'тия.")]),
]

# L8 — 3–4 класс: 120–160 слов, рассказ с завязкой и развязкой, описания, прямая речь.
L8 = [
 ("сыщики", "Одна'жды у'тром сосе'дка тётя Га'ля вы'шла во двор расстро'енная. — Ребя'та, я потеря'ла ключи' от кварти'ры! — сказа'ла она'. — Вчера' ве'чером они' бы'ли у меня' в карма'не. Ерла'н, Ами'на и Ди'ма реши'ли помо'чь. — Мы бу'дем как настоя'щие сы'щики, — сказа'л Ерла'н. Снача'ла они' расспроси'ли тётю Га'лю, где она' была' вчера'. Она' ходи'ла в магази'н, сиде'ла на скаме'йке и корми'ла голубе'й. Ребя'та обыска'ли скаме'йку, но ключе'й там не оказа'лось. Тогда' Ами'на заме'тила на ве'тке ста'рого клёна соро'ку. У неё в клю'ве блесте'л ма'ленький брело'к. — Соро'ки лю'бят всё блестя'щее! — вспо'мнил Ди'ма. Ребя'та подошли' к де'реву и уви'дели наверху' гнездо'. Па'па Ерла'на принёс ле'стницу и осторо'жно загляну'л в него'. Там лежа'ли фа'нтики, пу'говицы, ло'жечка и свя'зка ключе'й! Тётя Га'ля так обра'довалась, что испекла' для сы'щиков це'лый пиро'г.", [("сы'щик", "Сы'щик — э'то тот, кто и'щет пропа'вшее и разга'дывает та'йны."), ("брело'к", "Брело'к — э'то ма'ленькое украше'ние на свя'зке ключе'й.")]),
 ("палатка", "Ле'том Тиму'р с па'пой ночева'ли в пала'тке на берегу' реки'. Па'па бы'стро усну'л и захрапе'л, а Тиму'р лежа'л и слу'шал ночны'е зву'ки. Ему' совсе'м не хоте'лось спать. Плеска'лась вода', вдалеке' крича'ла пти'ца. Над пала'ткой пища'ли комары', а в траве' стрекота'ли кузне'чики. Вдруг ря'дом с пала'ткой послы'шался шо'рох. Шур, шур, топ, топ. Тиму'р за'мер. Шо'рох прибли'зился, а пото'м зазвене'ла ми'ска, кото'рую они' оста'вили у костра'. — Па'па, — шёпотом позва'л Тиму'р. — Там зверь! Па'па просну'лся, взял фона'рик и вы'глянул нару'жу. В луче' све'та сиде'л ёжик и дово'льно доеда'л их макаро'ны. Он фы'ркнул, бу'дто сказа'л спаси'бо, и неторопли'во ушёл в траву'. — Вот како'й у нас стра'шный зверь, — засмея'лся па'па. — Гро'зный пожира'тель макаро'н! Тиму'р то'же засмея'лся и вско'ре усну'л. А у'тром они' уви'дели на песке' цепо'чку ма'леньких следо'в, кото'рая вела' пря'мо к их котелку'.", [("шо'рох", "Шо'рох — э'то ти'хий шурша'щий звук."), ("неторопли'во", "Неторопли'во — зна'чит ме'дленно, без спе'шки.")]),
 ("щенок", "В феврале' в Костана'е три дня бушева'л бура'н. Когда' он наконе'ц ути'х, Ари'на с па'пой пошли' в магази'н. У гараже'й Ари'на услы'шала то'нкий писк. Под сугро'бом ме'жду гаража'ми сиде'л ма'ленький щено'к. Он весь дрожа'л, а на уша'х у него' висе'ли сосу'льки. — Па'па, он замёрзнет! — испуга'лась Ари'на. Па'па осторо'жно доста'л щенка' и спря'тал его' под ку'ртку. До'ма они' заверну'ли его' в полоте'нце и да'ли тёплого молока'. Щено'к жа'дно вы'лакал всё до после'дней ка'пли и усну'л у батаре'и. Ари'на сиде'ла ря'дом и боя'лась пошевели'ться. Ве'чером па'па сказа'л, что щено'к, наве'рное, бездо'мный. — Тогда' он бу'дет на'шим? — с наде'ждой спроси'ла Ари'на. Ма'ма и па'па перегляну'лись и улыбну'лись. — Бу'дет, — сказа'ла ма'ма. — То'лько приду'май ему' и'мя. Ари'на посмотре'ла на щенка', кото'рый сла'дко сопе'л во сне. — Бура'н! Потому' что мы нашли' его' по'сле бура'на. Так в их семье' появи'лся но'вый друг.", [("бура'н", "Бура'н — э'то си'льная сне'жная бу'ря в степи'."), ("бездо'мный", "Бездо'мный — зна'чит тот, у кого' нет до'ма и хозя'ина."), ("перегляну'лись", "Перегляну'лись — зна'чит посмотре'ли друг на дру'га.")]),
 ("доклад", "Учи'тельница попроси'ла ка'ждого подгото'вить небольшо'й докла'д. Ди'ма вы'брал те'му о ко'смосе. Всю неде'лю он чита'л кни'ги, смотре'л фи'льмы и рисова'л плака'т с плане'тами. Он узна'л, что на Ма'рсе есть са'мая высо'кая гора' в Со'лнечной систе'ме, а на Юпи'тере бушу'ет бу'ря, кото'рая дли'тся уже' со'тни лет. Но чем бли'же был день выступле'ния, тем бо'льше Ди'ма волнова'лся. — А вдруг я всё забу'ду? — говори'л он ма'ме. — Тогда' посмотри' на свой плака'т, — сове'товала ма'ма. — Он тебе' подска'жет. И вот Ди'ма вы'шел к доске'. Коле'ни у него' дрожа'ли, и пе'рвые слова' он сказа'л о'чень ти'хо. Но пото'м он посмотре'л на кра'сный Марс на плака'те и вспо'мнил, как интере'сно ему' бы'ло чита'ть. Го'лос у Ди'мы окре'п, и он рассказа'л всё, что знал. Когда' он зако'нчил, класс захло'пал. — А мо'жно ещё про чёрные ды'ры? — спроси'л Тиму'р с за'дней па'рты. Ди'ма улыбну'лся. Тепе'рь он гото'в был расска'зывать о ко'смосе хоть це'лый день.", [("докла'д", "Докла'д — э'то расска'з на за'данную те'му пе'ред слу'шателями."), ("окре'п", "Окре'п — зна'чит стал си'льным и уве'ренным.")]),
 ("дракон", "В высо'ких гора'х жила' семья' драко'нов. Все они' пари'ли над верши'нами и игра'ли с облака'ми. То'лько ма'ленький драко'н Гром никогда' не взлета'л. Он о'чень боя'лся высоты'. Ста'ршая сестра' дразни'ла его', а ма'ма вздыха'ла. Одна'жды в уще'лье сорва'лся ма'ленький козлёнок. Он стоя'л на у'зком усту'пе над про'пастью и жа'лобно бле'ял. Взро'слые драко'ны улете'ли далеко' на охо'ту, и помо'чь бы'ло не'кому. Гром посмотре'л вниз, и у него' закружи'лась голова'. — Я не смогу'! — прошепта'л он. Но козлёнок бле'ял так жа'лобно, что Гром зажму'рился и пры'гнул. Он раскры'л кры'лья, и во'здух подхвати'л его', как ладо'ни. Гром подлете'л к усту'пу, осторо'жно взял козлёнка ла'пами и по'днял его' наве'рх. Когда' ве'чером верну'лись взро'слые, Гром уже' кружи'л над гора'ми вме'сте с ла'сточками. — Ты лета'ешь! — удиви'лась сестра'. — Про'сто мне о'чень на'до бы'ло помо'чь, — отве'тил Гром.", [("уще'лье", "Уще'лье — э'то у'зкая глубо'кая доли'на ме'жду гора'ми."), ("усту'п", "Усту'п — э'то ма'ленькая площа'дка на круто'й скале'."), ("про'пасть", "Про'пасть — э'то о'чень глубо'кий обры'в.")]),
 ("мотоцикл", "У де'душки Тиму'ра в гараже' стои'т ста'рый мотоци'кл. Он стоя'л там так до'лго, что покры'лся пы'лью и паути'ной. — Де'душка, а он ещё е'здит? — спроси'л одна'жды Тиму'р. — Давно' не е'здит, — вздохну'л де'душка. — А в мо'лодости я объе'здил на нём полстраны'. — Дава'й его' почи'ним! — предложи'л Тиму'р. Де'душка улыбну'лся, и они' взяли'сь за рабо'ту. Ка'ждые выходны'е они' разбира'ли мото'р, чи'стили дета'ли и меня'ли ста'рые шла'нги. Тиму'р научи'лся держа'ть га'ечный ключ и отлича'ть болт от винта'. Ру'ки у него' ста'ли чёрными от ма'сла, но он был сча'стлив. Че'рез ме'сяц де'душка запра'вил мотоци'кл бензи'ном и нажа'л на педа'ль. Мото'р ка'шлянул, чихну'л и вдруг гро'мко затарахте'л! — Получи'лось! — закрича'л Тиму'р. Де'душка посади'л вну'ка сза'ди, и они' ме'дленно прое'хали по у'лице. Сосе'ди выгля'дывали из о'кон и маха'ли им рука'ми. — Пе'рвый раз за два'дцать лет, — сказа'л де'душка, и глаза' у него' блесте'ли.", [("паути'на", "Паути'на — э'то се'тка, кото'рую плетёт пау'к."), ("га'ечный ключ", "Га'ечный ключ — э'то инструме'нт, кото'рым закру'чивают га'йки и болты'."), ("затарахте'л", "Затарахте'л — зна'чит на'чал гро'мко и ча'сто стуча'ть.")]),
 ("вратарь", "В фина'ле шко'льного турни'ра кома'нда Ерла'на игра'ла с са'мыми си'льными сопе'рниками. Но пе'ред игро'й случи'лась беда'. Врата'рь Са'ша заболе'л и оста'лся до'ма. — Кто вста'нет на воро'та? — спроси'л тре'нер. Все молча'ли. Ерла'н всегда' игра'л в нападе'нии и никогда' не стоя'л в воро'тах. Но он сде'лал шаг вперёд. — Я попро'бую. Тре'нер вы'дал ему' перча'тки, кото'рые бы'ли велики' на два разме'ра. Игра' начала'сь, и сопе'рники сра'зу пошли' в ата'ку. Пе'рвый уда'р Ерла'н отби'л ного'й, второ'й пойма'л в прыжке'. В пе'рвом та'йме Тиму'р заби'л гол, и все повеселе'ли. На трибу'не крича'ли ребя'та со всей шко'лы. За две мину'ты до конца' судья' назна'чил пена'льти. Ерла'н стоя'л в воро'тах, и се'рдце у него' стуча'ло, как бараба'н. Напада'ющий разбежа'лся и уда'рил. Ерла'н пры'гнул в ле'вый у'гол и отби'л мяч ко'нчиками па'льцев! Свисто'к! Игра' око'нчена, и кома'нда Ерла'на победи'ла со счётом оди'н — ноль. — Ты наш геро'й! — крича'ли ребя'та и подбра'сывали Ерла'на вверх.", [("сопе'рник", "Сопе'рник — э'то тот, с кем ты соревну'ешься."), ("пена'льти", "Пена'льти — э'то уда'р по воро'там с бли'зкого расстоя'ния, кото'рый ну'жно отби'ть одному' вратарю'."), ("трибу'на", "Трибу'на — э'то ряды' мест для зри'телей на стадио'не.")]),
 ("сундук", "В ко'мнате у ба'бушки стои'т ста'рый сунду'к с ко'ваными угла'ми. Ами'не всегда' бы'ло интере'сно, что внутри'. Одна'жды ба'бушка откры'ла его' и позвала' вну'чку. В сундуке' лежа'ли вы'шитые полоте'нца, сере'бряные украше'ния и то'лстый альбо'м с фотогра'фиями. Ба'бушка доста'ла пожелте'вшую фотогра'фию. На ней был молодо'й мужчи'на в фо'рме лётчика. — Кто э'то? — спроси'ла Ами'на. — Э'то твой праде'душка Касы'м, — ти'хо отве'тила ба'бушка. — Он был лётчиком и учи'л молоды'х пило'тов. А ещё он о'чень люби'л не'бо и звёзды. Ами'на до'лго рассма'тривала фотогра'фию. У праде'душки бы'ли таки'е же тёмные бро'ви, как у неё, и така'я же улы'бка. — Я похо'жа на него'! — удиви'лась она'. — О'чень, — улыбну'лась ба'бушка. — Он то'же люби'л задава'ть вопро'сы. Ве'чером Ами'на нарисова'ла самолёт и написа'ла на нём и'мя праде'душки. Тепе'рь э'тот рису'нок то'же лежи'т в сундуке', ря'дом с его' фотогра'фией.", [("сунду'к", "Сунду'к — э'то большо'й деревя'нный я'щик с кры'шкой для веще'й."), ("ко'ваный", "Ко'ваный — зна'чит сде'ланный из мета'лла кузнецо'м."), ("праде'душка", "Праде'душка — э'то па'па твоего' де'душки и'ли ба'бушки.")]),
 ("выставка", "В шко'ле проходи'ла вы'ставка изобрете'ний. Ерла'н и Тиму'р це'лый ме'сяц собира'ли ро'бота, кото'рый уме'ет полива'ть цветы'. Ро'бот сам находи'л горшо'к, проверя'л, суха'я ли земля', и включа'л ма'ленький насо'с. Но за пять мину'т до прихо'да жюри' ро'бот вдруг переста'л слу'шаться. Он крути'лся на ме'сте и мига'л кра'сной ла'мпочкой. — Всё пропа'ло! — схвати'лся за го'лову Тиму'р. — Не пани'куй, — сказа'л Ерла'н, хотя' у него' самого' дрожа'ли ру'ки. — Дава'й прове'рим всё по поря'дку. Они' прове'рили мото'р, пото'м програ'мму, пото'м провода'. Оди'н про'вод отошёл от пла'ты. Ерла'н аккура'тно вста'вил его' на ме'сто, и ро'бот о'жил. Когда' подошло' жюри', ро'бот подъе'хал к фи'кусу и ла'сково поли'л его'. Учителя' заулыба'лись. А когда' объяви'ли победи'телей, ребя'та узна'ли, что получи'ли пе'рвое ме'сто. — Хорошо', что ты не запаникова'л, — сказа'л Тиму'р. — Я запаникова'л, — призна'лся Ерла'н. — Про'сто ти'хо.", [("вы'ставка", "Вы'ставка — э'то ме'сто, где пока'зывают интере'сные рабо'ты."), ("пани'ковать", "Пани'ковать — зна'чит так испуга'ться, что не мо'жешь ду'мать."), ("пла'та", "Пла'та — э'то пласти'нка с проводка'ми и дета'лями внутри' прибо'ра.")]),
 ("спасатели", "Одна'жды кот Ба'рсик погна'лся за воробьём и взлете'л на высо'кий то'поль. Воробе'й улете'л, а Ба'рсик оста'лся на са'мой верху'шке. Он вцепи'лся в ве'тку и жа'лобно мяу'кал. Ди'ма звал его', ма'ма шурша'ла паке'том с ко'рмом, но Ба'рсик то'лько кре'пче держа'лся и мяу'кал ещё гро'мче. — Он бои'тся слезть! — испуга'лся Ди'ма. — Звони'м спаса'телям. Че'рез полчаса' во двор въе'хала кра'сная маши'на. Спаса'тели в ка'сках раздви'нули дли'нную ле'стницу, и оди'н из них на'чал поднима'ться к Ба'рсику. Все сосе'ди вы'шли на балко'ны и затаи'ли дыха'ние. Но едва' спаса'тель протяну'л к коту' ру'ку, как Ба'рсик фы'ркнул, ло'вко спусти'лся по стволу' и спры'гнул на траву'. Он споко'йно облиза'л ла'пу и ва'жно пошёл домо'й, бу'дто ничего' не случи'лось. Спаса'тель засмея'лся. — Тако'е быва'ет ча'сто, — сказа'л он. — Ко'шки лю'бят, что'бы на них смотре'ло побо'льше зри'телей. Ди'ма поблагодари'л спаса'телей, а Ба'рсика в тот ве'чер оста'вили без десе'рта.", [("спаса'тель", "Спаса'тель — э'то челове'к, кото'рый помога'ет лю'дям и живо'тным в беде'."), ("затаи'ли дыха'ние", "Затаи'ли дыха'ние — зна'чит за'мерли и почти' не дыша'ли от волне'ния.")]),
 ("подарок", "До ма'миного дня рожде'ния остава'лась неде'ля, а у Але'ма бы'ло всего' три'ста те'нге. На таки'е де'ньги хоро'ший пода'рок не ку'пишь. Але'м до'лго ду'мал и реши'л сде'лать пода'рок сам. Он вспо'мнил, что ма'ма давно' хоте'ла по'лочку для цвето'в на подоко'ннике. Вме'сте с де'душкой они' вы'брали в сара'е ро'вные до'ски. Де'душка показа'л, как отме'рить и отпили'ть, а Але'м сам зачи'стил края' нажда'чной бума'гой. Пото'м он покра'сил по'лочку в голубо'й цвет и нарисова'л на ней ма'ленькие рома'шки. Ка'ждый ве'чер он пря'тал свою' рабо'ту под крова'тью, что'бы ма'ма не уви'дела. В день рожде'ния Але'м вручи'л ма'ме пода'рок, завёрнутый в газе'ту. Ма'ма разверну'ла его' и а'хнула. — Неуже'ли ты сам сде'лал? — Сам, — го'рдо отве'тил Але'м. — То'лько де'душка немно'го помога'л. Ма'ма обняла' сы'на и сра'зу поста'вила на по'лочку свои' фиа'лки. — Э'то са'мый лу'чший пода'рок, — сказа'ла она'. — Потому' что в нём твоя' забо'та.", [("нажда'чная бума'га", "Нажда'чная бума'га — э'то шерша'вая бума'га, кото'рой шлифу'ют де'рево."), ("фиа'лка", "Фиа'лка — э'то ма'ленький ко'мнатный цвето'к с ба'рхатными ли'стьями.")]),
 ("верблюд", "В стари'ну, когда' степь была' ещё молодо'й, верблю'д был ро'вным и гла'дким, как ло'шадь. Он о'чень люби'л пить во'ду и це'лыми дня'ми стоя'л у реки'. Одна'жды пришла' за'суха. Ре'ки обмеле'ли, озёра вы'сохли, и все зве'ри отпра'вились иска'ть во'ду. — Как же мы перейдём пусты'ню? — горева'ли они'. — Там нет ни ка'пли воды'! Тогда' му'драя черепа'ха сказа'ла верблю'ду: — Ты са'мый си'льный из нас. Набери' воды' про запа'с и спрячь её на спине'. Верблю'д пил це'лый день, и на спине' у него' вы'рос большо'й горб. Пото'м он вёл звере'й че'рез пески' и дели'лся с ни'ми свои'ми запа'сами. С тех пор у верблю'да есть горб. Пра'вда, учёные говоря'т, что в горбе' не вода', а жир. Но верблю'д и в са'мом де'ле мо'жет до'лго обходи'ться без воды', совсе'м как в э'той ска'зке.", [("за'суха", "За'суха — э'то вре'мя, когда' до'лго нет дождя'."), ("обмеле'ли", "Обмеле'ли — зна'чит ста'ли ме'лкими, воды' ста'ло ма'ло."), ("про запа'с", "Про запа'с — зна'чит на пото'м, на вся'кий слу'чай.")]),
 ("горы", "Ле'том Ерла'н с па'пой пошли' в го'ры Алата'у. Тропа' вела' вверх ме'жду высо'кими е'лями, и отту'да открыва'лся вид на весь го'род. Они' добрали'сь до водопа'да и устро'или прива'л. Но пока' они' е'ли бутербро'ды, с верши'н спусти'лся густо'й тума'н. Всё вокру'г ста'ло се'рым и бе'лым. Тропи'нку бы'ло совсе'м не ви'дно. — Па'па, мы заблуди'лись? — испуга'лся Ерла'н. — Не волну'йся, — споко'йно сказа'л па'па. — Слы'шишь, шуми'т руче'й? Он течёт вниз, к доро'ге. Пойдём вдоль него'. Они' осторо'жно пошли' на шум воды', держа'сь за ру'ки. Ерла'н счита'л шаги', что'бы не боя'ться. Иногда' им приходи'лось перелеза'ть че'рез ка'мни и пова'ленные дере'вья. Че'рез час тума'н стал реде'ть, и внизу' показа'лась знако'мая доро'га. — Ура'! — закрича'л Ерла'н. — Руче'й нас вы'вел! — В гора'х гла'вное не паникова'ть, — улыбну'лся па'па. — И всегда' по'мнить, куда' течёт вода'.", [("прива'л", "Прива'л — э'то остано'вка для о'тдыха в пути'."), ("реде'ть", "Реде'ть — зна'чит станови'ться ре'же и прозра'чнее.")]),
 ("асыки", "На Науры'з во дворе' у ба'бушки собрали'сь все ро'дственники. Взро'слые накрыва'ли столы', а де'ти игра'ли в асы'ки. Э'то стари'нная каза'хская игра' с ко'сточками. Ну'жно ме'тким броско'м вы'бить ко'сточки сопе'рника из кру'га. Тиму'р игра'л впервы'е и всё вре'мя прома'хивался. Его' двою'родный брат Айда'р выи'грывал раз за ра'зом. — Не расстра'ивайся, — сказа'л де'душка и присе'л ря'дом. — Я научу' тебя' одному' секре'ту. Не смотри' на свою' ру'ку, смотри' то'лько на цель. И броса'й не си'льно, а то'чно. Тиму'р прице'лился, затаи'л дыха'ние и бро'сил. Щёлк! Ко'сточка Айда'ра вы'летела из кру'га. — Попа'л! — закрича'л Тиму'р. Пото'м он попа'л ещё и ещё. К обе'ду он уже' почти' догна'л бра'та. — Тебе' про'сто везёт, — проворча'л Айда'р. — Не везёт, — улыбну'лся де'душка. — Про'сто он внима'тельно слу'шал. Пото'м вся семья' се'ла за стол и е'ла пра'здничный суп из семи' проду'ктов.", [("асы'к", "Асы'к — э'то ко'сточка для стари'нной каза'хской игры'."), ("двою'родный брат", "Двою'родный брат — э'то сын твоего' дя'ди и'ли тёти."), ("прице'лился", "Прице'лился — зна'чит напра'вил бросо'к то'чно в цель.")]),
 ("тюлень", "Ле'том Ами'на с роди'телями отдыха'ла на Каспи'йском мо'ре в Акта'у. Мо'ре бы'ло тёплым и голубы'м, а бе'рег камени'стым. Одна'жды ра'но у'тром Ами'на уви'дела на ка'мнях тёмное пятно'. Пятно' пошевели'лось и по'дняло го'лову. На неё смотре'ли больши'е чёрные глаза', а под но'сом торча'ли жёсткие усы'. — Ма'ма, тут соба'ка в мо'ре! — кри'кнула Ами'на. — Э'то не соба'ка, а тюле'нь, — сказа'ла подоше'дшая ма'ма. — Каспи'йский тюле'нь. Он живёт то'лько здесь и бо'льше нигде' на све'те. Тюле'нь неуклю'же перевали'лся с ка'мня на ка'мень и плю'хнулся в во'ду. В воде' он сра'зу стал ло'вким и бы'стрым. Он ныря'л, выны'ривал и как бу'дто игра'л с ни'ми. — Почему' их ре'дко ви'дят? — спроси'ла Ами'на. — Тюле'ней стано'вится ма'ло, — вздохну'ла ма'ма. — Поэ'тому их на'до бере'чь и не беспоко'ить. Ами'на не ста'ла подходи'ть бли'же. Она' про'сто помаха'ла тюле'ню руко'й и пожела'ла ему' счастли'вого пути'.", [("тюле'нь", "Тюле'нь — э'то морско'й зверь с ла'стами вме'сто лап."), ("неуклю'же", "Неуклю'же — зна'чит нело'вко, косола'по.")]),
 ("ужин", "В суббо'ту ма'ма уе'хала к подру'ге, и па'па объяви'л, что сам пригото'вит у'жин. — Бу'дет пи'цца! — торже'ственно сказа'л он. Ди'ма и Ари'на ра'достно захло'пали. Па'па наде'л ма'мин фа'ртук и откры'л кни'гу реце'птов. Снача'ла он заме'шивал те'сто, и мука' разлете'лась по всей ку'хне. Пото'м он так стара'тельно ре'зал лук, что распла'кался. — Па'па, не плачь! — утеша'ла его' Ари'на. — Э'то не я, э'то лук, — всхли'пывал па'па. Наконе'ц пи'цца отпра'вилась в духо'вку. Па'па присе'л на мину'тку и случа'йно задрема'л. Просну'лся он от за'паха ды'ма. Пи'цца получи'лась чёрной, как у'голь. В э'тот моме'нт верну'лась ма'ма. Она' посмотре'ла на бе'лую от муки' ку'хню, на запла'канного па'пу и на чёрную пи'ццу. — Ну что, по'вар, — засмея'лась она', — зака'зываем пельме'ни? В тот ве'чер вся семья' е'ла пельме'ни и хохота'ла до слёз.", [("заме'шивал", "Заме'шивал те'сто — зна'чит переме'шивал муку' с водо'й, пока' не полу'чится те'сто."), ("всхли'пывал", "Всхли'пывал — зна'чит пла'кал, ча'сто вздыха'я."), ("духо'вка", "Духо'вка — э'то горя'чий шкаф в плите', где пеку'т.")]),
 ("звездопад", "В середи'не а'вгуста па'па разбуди'л Тиму'ра по'здно ве'чером. — Пойдём на кры'шу, сего'дня звездопа'д! Они' взя'ли пле'ды и те'рмос с ча'ем и подняли'сь на пло'скую кры'шу сара'я. Не'бо бы'ло чёрное, без еди'ного о'блачка, и звёзд на нём бы'ло не сосчита'ть. Тиму'р лёг на спи'ну и стал ждать. Вдруг по не'бу пронесла'сь я'ркая черта'. — Па'па, звезда' упа'ла! — Э'то не звезда', а ма'ленький ка'мешек из ко'смоса, — объясни'л па'па. — Он влета'ет в во'здух на огро'мной ско'рости и сгора'ет. Мы ви'дим, как он све'тится. — А жела'ние загада'ть мо'жно? — Мо'жно, — улыбну'лся па'па. — Говоря'т, сбу'дется. Тиму'р загада'л стать космона'втом. Пото'м пролете'ла ещё одна' звезда', и ещё одна'. За час они' насчита'ли два'дцать семь метео'ров. Тиму'р засну'л пря'мо на кры'ше, укры'вшись пле'дом, и па'па на рука'х отнёс его' в крова'ть.", [("звездопа'д", "Звездопа'д — э'то ночь, когда' по не'бу пролета'ет мно'го метео'ров."), ("метео'р", "Метео'р — э'то я'ркая полоса' в не'бе от сгора'ющего косми'ческого ка'мешка.")]),
 ("бабушка", "Ба'бушка Ерла'на живёт в ау'ле, далеко' от го'рода. Ей купи'ли но'вый смартфо'н, но она' ника'к не могла' в нём разобра'ться. Ерла'н реши'л научи'ть её звони'ть по ви'део. Он приду'мал просту'ю инстру'кцию и нарисова'л её на листо'чке. Зелёная кно'пка, что'бы отве'тить, кра'сная, что'бы зако'нчить. По телефо'ну он терпели'во объясня'л ба'бушке ка'ждый шаг. Пе'рвый раз ба'бушка случа'йно сбро'сила звоно'к. Во второ'й раз Ерла'н це'лых пять мину'т ви'дел то'лько потоло'к и ба'бушкин нос. Пото'м ба'бушка до'лго иска'ла, где у телефо'на ка'мера. — Ба'бушка, поверни' телефо'н! — смея'лся он. Наконе'ц на экра'не появи'лось ба'бушкино лицо' в цвето'чном платке'. — Ой, я тебя' ви'жу! — обра'довалась ба'бушка. — Как ты вы'рос! Тепе'рь они' разгова'ривают ка'ждый ве'чер. Ба'бушка пока'зывает Ерла'ну ягня'т и цыпля'т, а Ерла'н пока'зывает ей свои' пятёрки. — Како'й ты у меня' у'мный учи'тель, — говори'т ба'бушка. И Ерла'н о'чень горди'тся свое'й учени'цей.", [("смартфо'н", "Смартфо'н — э'то телефо'н с экра'ном, как ма'ленький компью'тер."), ("инстру'кция", "Инстру'кция — э'то спи'сок шаго'в, что и как де'лать."), ("терпели'во", "Терпели'во — зна'чит споко'йно, не сердя'сь и не торопя'сь.")]),
 ("карта", "В день рожде'ния Ди'ма нашёл под поду'шкой свёрнутый лист. Э'то была' ка'рта! На ней бы'ли нарисо'ваны дом, двор и большо'й кре'стик у ста'рой я'блони. Внизу' бы'ло напи'сано, что начина'ть на'до с холоди'льника. Ди'ма бро'сился на ку'хню. На две'рце холоди'льника висе'ла запи'ска. В ней говори'лось, что сле'дующая подска'зка спря'тана там, где спят боти'нки. В прихо'жей, в ста'ром боти'нке, лежа'ла но'вая запи'ска, пото'м ещё одна' в почто'вом я'щике, пото'м под ко'вриком. Ди'ма бе'гал по всему' до'му и двору', а ста'рший брат Тиму'р ходи'л за ним и зага'дочно улыба'лся. Наконе'ц Ди'ма добра'лся до я'блони. У её корне'й была' све'жая земля'. Ди'ма взял сово'к и на'чал копа'ть. Вско'ре сово'к сту'кнулся о жестяну'ю коро'бку. Внутри' лежа'л настоя'щий ко'мпас и запи'ска. В ней бы'ло напи'сано, что тепе'рь Ди'ма никогда' не заблу'дится. — Э'то ты всё приду'мал? — спроси'л Ди'ма. — Я, — призна'лся Тиму'р. — Тебе' понра'вилось? Ди'ма вме'сто отве'та кре'пко о'бнял бра'та.", [("ко'мпас", "Ко'мпас — э'то прибо'р со стре'лкой, кото'рая всегда' пока'зывает на се'вер."), ("подска'зка", "Подска'зка — э'то намёк, кото'рый помога'ет найти' отве'т."), ("сово'к", "Сово'к — э'то ма'ленькая лопа'тка.")]),
 ("ягнёнок", "Весно'й в ау'ле у де'душки родили'сь ягня'та. Оди'н из них, са'мый ма'ленький, роди'лся сла'бым, и овца' не ста'ла его' корми'ть. — Без молока' он не вы'живет, — сказа'л де'душка и посмотре'л на Але'ма. — Возьмёшься за него'? Але'м кивну'л. Он корми'л ягнёнка из буты'лочки с со'ской ка'ждые три часа', да'же но'чью. Ягнёнок жа'дно соса'л молоко' и смешно' виля'л хво'стиком. Але'м назва'л его' Бу'бликом, потому' что тот всё вре'мя свора'чивался клубко'м. Че'рез две неде'ли Бу'блик окре'п и стал бе'гать за Але'мом по пята'м, как щено'к. Он ходи'л за ним к коло'дцу, в огоро'д и да'же пыта'лся зайти' в дом. В конце' ле'та, когда' на'до бы'ло уезжа'ть в го'род, Але'м до'лго проща'лся с Бу'бликом. — Не волну'йся, — сказа'л де'душка. — Я за ним присмотрю'. А когда' ты прие'дешь сле'дующим ле'том, он тебя' узна'ет. И пра'вда, че'рез год из ста'да вы'бежал кудря'вый бара'шек и бро'сился пря'мо к Але'му.", [("со'ска", "Со'ска — э'то рези'новый наконе'чник на буты'лочке для кормле'ния малыше'й."), ("по пята'м", "Ходи'ть по пята'м — зна'чит не отстава'ть ни на шаг."), ("кудря'вый", "Кудря'вый — зна'чит с завитка'ми, как бара'шек.")]),
]

# L9 — 4 класс: 170–230 слов, познавательные и художественные тексты, причастные и деепричастные обороты.
L9 = [
 ("байконур", "Двена'дцатого апре'ля ты'сяча девятьсо'т шестьдеся'т пе'рвого го'да с космодро'ма Байкону'р стартова'ла раке'та, кото'рая навсегда' измени'ла исто'рию челове'чества. В косми'ческом корабле' Восто'к находи'лся молодо'й лётчик Ю'рий Гага'рин. Пе'ред са'мым ста'ртом он улыбну'лся и произнёс знамени'тое сло'во. — Пое'хали! Раке'та, оставля'ющая за собо'й о'гненный след, бы'стро скры'лась в не'бе. Гага'рин облете'л вокру'г Земли' за сто во'семь мину'т. Всё э'то вре'мя за полётом с волне'нием следи'ли учёные, а Гага'рин споко'йно сообща'л на Зе'млю о своём самочу'вствии. Гля'дя в иллюмина'тор, он уви'дел на'шу плане'ту со стороны', окружённую то'нкой голубо'й ды'мкой. Никто' из люде'й ра'ньше не ви'дел тако'го зре'лища. Верну'вшись на Зе'млю, Гага'рин рассказа'л, что Земля' о'чень краси'вая и её ну'жно бере'чь. Ка'ждый год двена'дцатого апре'ля во всём ми'ре отмеча'ют День космона'втики. Космодро'м Байкону'р нахо'дится в каза'хской степи', недалеко' от реки' Сырдарья'. Его' постро'или здесь, потому' что в ро'вной безлю'дной степи' мно'го со'лнечных дней, а чем ю'жнее космодро'м, тем ле'гче раке'там взлета'ть. С тех пор с Байкону'ра стартова'ли со'тни раке'т. Отсю'да же в ты'сяча девятьсо'т девяно'сто пе'рвом году' полете'л в ко'смос Тохта'р Аубаки'ров, пе'рвый космона'вт из Казахста'на. Сего'дня мно'гие ребя'та, мечта'ющие о звёздах, приезжа'ют в музе'й космодро'ма, что'бы уви'деть настоя'щие раке'ты.", [("космодро'м", "Космодро'м — э'то ме'сто, отку'да запуска'ют раке'ты в ко'смос."), ("иллюмина'тор", "Иллюмина'тор — э'то кру'глое окно' в корабле' и'ли самолёте.")]),
 ("сайгаки", "В бескра'йних степя'х Казахста'на живу'т удиви'тельные антило'пы сайга'ки. Их легко' узна'ть по большо'му мя'гкому но'су, похо'жему на коро'ткий хо'бот. Тако'й нос не случа'йность. Ле'том, когда' по степи' несу'тся сухи'е ве'тры, он очища'ет во'здух от пы'ли, а зимо'й согрева'ет моро'зный во'здух, пре'жде чем тот попадёт в лёгкие. Сайга'ки бе'гают о'чень бы'стро, развива'я ско'рость до восьми'десяти киломе'тров в час. Спаса'ясь от волко'в, они' мча'тся огро'мными стада'ми, и земля' гуди'т под ты'сячами копы'т. Ка'ждую весну' са'мки ухо'дят в укро'мные места', где на свет появля'ются малыши'. Новорождённые сайгача'та лежа'т в траве', прижа'вшись к земле', и их почти' невозмо'жно заме'тить. Уже' че'рез не'сколько дней малыши' мо'гут бе'гать наравне' со взро'слыми. Не'сколько лет наза'д сайга'ков в степи' оста'лось о'чень ма'ло. Браконье'ры охо'тились на них ра'ди рого'в, а суро'вые зи'мы и боле'зни уноси'ли це'лые стада'. Тогда' в Казахста'не запрети'ли охо'ту на сайга'ков и созда'ли запове'дники. Учёные, следя'щие за стада'ми, ста'ли счита'ть живо'тных с вертолётов. И сайга'ки спасли'сь! Сего'дня их сно'ва бо'льше миллио'на, и они', как в стари'ну, свобо'дно кочу'ют по степи'. Уви'деть огро'мное ста'до сайга'ков, бегу'щее по весе'нней степи', — настоя'щая уда'ча для любо'го путеше'ственника.", [("браконье'р", "Браконье'р — э'то тот, кто охо'тится там, где запрещено'."), ("запове'дник", "Запове'дник — э'то ме'сто, где приро'ду охраня'ют и нельзя' охо'титься."), ("кочу'ют", "Кочу'ют — зна'чит перехо'дят с ме'ста на ме'сто.")]),
 ("ирбис", "Высоко' в гора'х Алата'у, где ска'лы покры'ты ве'чным сне'гом, живёт оди'н из са'мых таи'нственных звере'й плане'ты. Э'то сне'жный барс, и'ли и'рбис. Его' густа'я се'рая шерсть с тёмными пя'тнами помога'ет ему' сли'ться с ка'мнями, и уви'деть его' почти' невозмо'жно. Да'же учёные, изуча'ющие и'рбисов мно'го лет, ча'ще нахо'дят то'лько их следы'. Сне'жный барс прекра'сно приспосо'блен к жи'зни в гора'х. Широ'кие пуши'стые ла'пы, похо'жие на снегосту'пы, не даю'т ему' прова'ливаться в глубо'кий снег. Хвост, почти' тако'й же дли'нный, как те'ло, помога'ет держа'ть равнове'сие во вре'мя прыжко'в. А когда' барс ложи'тся спать, он укрыва'ется хвосто'м, как тёплым ша'рфом. Ведь но'чью в гора'х быва'ет о'чень хо'лодно. И'рбис мо'жет пры'гнуть так далеко', что перелета'ет че'рез у'зкие уще'лья. В Казахста'не сне'жного ба'рса о'чень лю'бят и уважа'ют. Крыла'тый барс изображён на гербе' Алматы', а мно'гие спортсме'ны и кома'нды но'сят его' и'мя. И'рбис занесён в Кра'сную кни'гу, и охо'титься на него' стро'го запрещено'. Лесники' и учёные ста'вят в гора'х фотолову'шки, кото'рые сра'зу снима'ют проходя'щего зве'ря. Так учёные узнаю'т, ско'лько ба'рсов живёт в гора'х. Иногда' на сни'мках появля'ется са'мка со смешны'ми пуши'стыми котя'тами, и э'то зна'чит, что и'рбисы в гора'х ещё живу'т и расту'т.", [("приспосо'блен", "Приспосо'блен — зна'чит хорошо' подхо'дит для жи'зни в тако'м ме'сте."), ("Кра'сная кни'га", "Кра'сная кни'га — э'то спи'сок ре'дких живо'тных и расте'ний, кото'рые на'до охраня'ть."), ("фотолову'шка", "Фотолову'шка — э'то ка'мера, кото'рая сама' фотографи'рует, когда' ря'дом дви'жется зверь.")]),
 ("небо", "Почему' не'бо голубо'е? Э'тот вопро'с задава'ли себе' лю'ди с древне'йших времён. Ока'зывается, отве'т спря'тан в са'мом со'лнечном све'те. Нам ка'жется, что свет Со'лнца бе'лый. На са'мом де'ле он состои'т из всех цвето'в ра'дуги, сме'шанных вме'сте. Убеди'ться в э'том мо'жно, гля'дя на ра'дугу по'сле дождя'. Ка'пли воды', вися'щие в во'здухе, разлага'ют бе'лый свет на кра'сный, ора'нжевый, жёлтый, зелёный, голубо'й, си'ний и фиоле'товый. Проходя' сквозь во'здух, со'лнечные лучи' ста'лкиваются с мельча'йшими части'цами, из кото'рых он состои'т. Си'ние и голубы'е лучи' рассе'иваются, то есть разлета'ются во все сто'роны, гора'здо сильне'е кра'сных. Поэ'тому, куда' бы мы ни посмотре'ли, отовсю'ду к нам прихо'дит голубо'й свет, и всё не'бо ка'жется голубы'м. А почему' зака'т кра'сный? Ве'чером, когда' Со'лнце опуска'ется к горизо'нту, его' лучи' прохо'дят сквозь о'чень то'лстый слой во'здуха. По доро'ге почти' весь си'ний свет рассе'ивается, и до нас добира'ются то'лько кра'сные и ора'нжевые лучи'. Вот почему' зака'ты окра'шивают облака' в тако'й я'ркий цвет. А на Луне', где во'здуха нет совсе'м, не'бо чёрное да'же днём. Космона'вты, побыва'вшие там, ви'дели над собо'й чёрное не'бо и ослепи'тельное Со'лнце.", [("части'цы", "Части'цы — э'то кро'шечные кусо'чки вещества', кото'рые не уви'деть глаза'ми."), ("рассе'иваются", "Рассе'иваются — зна'чит разлета'ются в ра'зные сто'роны."), ("горизо'нт", "Горизо'нт — э'то ли'ния, где не'бо как бу'дто встреча'ется с землёй.")]),
 ("вулкан", "Глубоко' под на'шими нога'ми, на расстоя'нии деся'тков киломе'тров, земля' раскалена' так си'льно, что ка'мни там пла'вятся. Распла'вленная го'рная поро'да называ'ется ма'гмой. Ма'гма ле'гче окружа'ющих её ка'мней, поэ'тому она' ме'дленно поднима'ется вверх, ища' тре'щины в земно'й коре'. Там, где ей удаётся вы'рваться нару'жу, рожда'ется вулка'н. Изверже'ние вулка'на — одно' из са'мых гро'зных зре'лищ на Земле'. Снача'ла из кра'тера вырыва'ются облака' па'ра и пе'пла, поднима'ясь на высоту' в не'сколько киломе'тров. Пото'м по скло'нам стека'ет раскалённая ла'ва, сжига'я всё на своём пути'. Ла'ва быва'ет горяче'е ты'сячи гра'дусов и све'тится в темноте' кра'сным све'том. Остыва'я, ла'ва затвердева'ет и превраща'ется в чёрный ка'мень. Так, слой за сло'ем, вулка'н выраста'ет всё вы'ше и вы'ше. Мно'гие вулка'ны давно' поту'хли и спят. Други'е, называ'емые де'йствующими, мо'гут просну'ться в любо'й моме'нт. Учёные, кото'рых называ'ют вулкано'логами, следя'т за ни'ми с по'мощью осо'бых прибо'ров. Они' замеча'ют да'же сла'бые толчки' и предупрежда'ют люде'й об опа'сности. Интере'сно, что вулка'ны не то'лько разруша'ют. Пе'пел, вы'павший на зе'млю, де'лает по'чву о'чень плодоро'дной, поэ'тому лю'ди и'здавна се'лятся у подно'жия вулка'нов. А мно'гие острова' в океа'не, наприме'р Гава'йи, — э'то верши'ны огро'мных подво'дных вулка'нов. В Казахста'не де'йствующих вулка'нов нет, но в гора'х мо'жно найти' следы' о'чень дре'вних изверже'ний.", [("ма'гма", "Ма'гма — э'то распла'вленный ка'мень глубоко' под землёй."), ("изверже'ние", "Изверже'ние — э'то когда' из вулка'на вырыва'ются ла'ва, пе'пел и газ."), ("плодоро'дный", "Плодоро'дная по'чва — э'то земля', на кото'рой хорошо' всё растёт.")]),
 ("яблоня", "Как вы ду'маете, отку'да пришли' я'блоки, кото'рые мы покупа'ем в магази'не? Учёные до'лго иска'ли ро'дину я'блони и в конце' концо'в нашли' её в Казахста'не. В предго'рьях Заили'йского Алата'у, недалеко' от Алматы', до сих пор расту'т ди'кие я'блоневые леса'. Гла'вное де'рево в них — я'блоня Си'верса. Её назва'ли в честь учёного, кото'рый одни'м из пе'рвых описа'л её. Учёные, сравни'вшие я'блони со всего' све'та, вы'яснили, что и'менно от неё произошли' почти' все культу'рные сорта'. Ди'кие я'блоки быва'ют са'мыми ра'зными. Одни' ма'ленькие и ки'слые, други'е кру'пные и сла'дкие, как мёд. Есть жёлтые, зелёные и румя'ные, с кра'сными бочка'ми. Ты'сячи лет наза'д купцы', проходи'вшие по Вели'кому шёлковому пути', бра'ли с собо'й са'мые вку'сные я'блоки и разноси'ли их семена' по ра'зным стра'нам. Так я'блоня из казахста'нских гор постепе'нно рассели'лась по всему' ми'ру. А сла'ву Алматы' принёс апо'рт, огро'мное я'блоко ве'сом иногда' до полукилогра'мма. Одного' тако'го я'блока хвата'ет, что'бы угости'ть всю семью'. Говоря'т, что его' арома'т мо'жно почу'вствовать, ещё не войдя' в сад. Сего'дня ди'кие я'блоневые леса' охраня'ют учёные и лесники'. Ведь е'сли они' исче'знут, мир потеря'ет бесце'нную кладову'ю, из кото'рой мо'жно вы'вести но'вые сорта', не боя'щиеся ни боле'зней, ни моро'зов.", [("предго'рья", "Предго'рья — э'то ни'зкие холмы' у подно'жия гор."), ("купцы'", "Купцы' — э'то торго'вцы, кото'рые вози'ли това'ры из страны' в страну'."), ("кладова'я", "Кладова'я — э'то ме'сто, где храня'т запа'сы.")]),
 ("олимпиада", "Бо'лее двух ты'сяч семисо'т лет наза'д в Дре'вней Гре'ции, в месте'чке Олимпи'я, прошли' пе'рвые Олимпи'йские и'гры. Их устра'ивали в честь бо'га Зе'вса раз в четы'ре го'да. Пока' шли состяза'ния, во всей Гре'ции объявля'лось переми'рие. Да'же враждова'вшие города' прекраща'ли во'йны, что'бы спортсме'ны и зри'тели могли' споко'йно добра'ться до Олимпи'и. Снача'ла соревнова'лись то'лько в бе'ге на одну' диста'нцию длино'й о'коло двухсо'т ме'тров. Пото'м доба'вили борьбу', прыжки' в длину', мета'ние ди'ска и копья', го'нки на колесни'цах. Победи'тели не получа'ли ни золоты'х меда'лей, ни де'нег. Их награжда'ли венко'м из ве'ток ди'кой масли'ны. Тако'й вено'к счита'лся са'мой почётной награ'дой на све'те. Но сла'ва чемпио'на была' так велика', что в его' родно'м го'роде ста'вили ему' па'мятник, а поэ'ты сочиня'ли о нём пе'сни. Мно'го веко'в спустя' Олимпи'йские и'гры бы'ли запрещены' и забы'ты. Возроди'л их францу'з Пьер де Куберте'н, мечта'вший, что спорт сдру'жит наро'ды. В ты'сяча восемьсо'т девяно'сто шесто'м году' в Афи'нах прошла' пе'рвая совреме'нная Олимпиа'да. Тогда' в ней уча'ствовали всего' две'сти со'рок оди'н спортсме'н, а сего'дня их бо'льше десяти' ты'сяч. Сего'дня на и'гры съезжа'ются спортсме'ны почти' из всех стран ми'ра, а пе'ред нача'лом соревнова'ний в Олимпи'и, как и в дре'вности, зажига'ют олимпи'йский ого'нь.", [("состяза'ния", "Состяза'ния — э'то соревнова'ния."), ("переми'рие", "Переми'рие — э'то вре'мя, когда' враги' договори'лись не воева'ть."), ("колесни'ца", "Колесни'ца — э'то дре'вняя пово'зка на двух колёсах, запряжённая лошадьми'.")]),
 ("бумага", "Тру'дно предста'вить на'шу жизнь без бума'ги. На ней печа'тают кни'ги и газе'ты, из неё де'лают тетра'ди и коро'бки. А ведь ты'сячи лет наза'д лю'ди писа'ли на гли'няных табли'чках, ка'мнях, ко'же живо'тных и ли'стьях пальм. Бума'гу изобрели' в Дре'внем Кита'е. По преда'нию, о'коло двух ты'сяч лет наза'д чино'вник по и'мени Цай Лунь приду'мал, как де'лать её из коры' шелкови'цы, ста'рых тря'пок и рыболо'вных сете'й. Всё э'то выма'чивали, толкли' в ка'шу, а пото'м то'нким сло'ем выкла'дывали на се'тку и суши'ли. Получа'лись то'нкие лёгкие листы', на кото'рых бы'ло удо'бно писа'ть ки'стью. Кита'йцы мно'го веко'в храни'ли секре'т изготовле'ния бума'ги, никому' его' не выдава'я. Говоря'т, что та'йна раскры'лась по'сле би'твы на реке' Тала'с, недалеко' от совреме'нного Тара'за. Среди' пле'нных оказа'лись кита'йские мастера', уме'вшие де'лать бума'гу. Их привезли' в Самарка'нд, и вско'ре бума'жные мастерски'е появи'лись по всему' Восто'ку. Отту'да, путеше'ствуя вме'сте с карава'нами, иску'сство изготовле'ния бума'ги дошло' до Евро'пы. Сего'дня бума'гу де'лают в основно'м из древеси'ны на огро'мных фа'бриках. Что'бы получи'ть одну' то'нну бума'ги, прихо'дится сруби'ть мно'го дере'вьев. Поэ'тому так ва'жно сдава'ть макулату'ру. Из ста'рых газе'т и тетра'дей мо'жно сде'лать но'вую бума'гу и сбере'чь живы'е леса'.", [("преда'ние", "Преда'ние — э'то расска'з о про'шлом, кото'рый передаю'т из поколе'ния в поколе'ние."), ("древеси'на", "Древеси'на — э'то де'рево как материа'л."), ("макулату'ра", "Макулату'ра — э'то ста'рая бума'га, кото'рую сдаю'т на перерабо'тку.")]),
 ("пчёлы", "Пчела', наше'дшая поля'ну с цвета'ми, не мо'жет рассказа'ть о ней слова'ми. Но она' уме'ет танцева'ть, и э'тот та'нец поня'тен всем пчёлам в у'лье. Э'то откры'тие сде'лал учёный Карл фон Фриш, мно'го лет наблюда'вший за пчёлами. За э'то откры'тие он получи'л Но'белевскую пре'мию. Верну'вшись в у'лей, разве'дчица начина'ет бе'гать по со'там, выпи'сывая восьмёрку. В середи'не восьмёрки она' бежи'т пря'мо, бы'стро виля'я брюшко'м. Направле'ние э'того бе'га пока'зывает, куда' лете'ть относи'тельно Со'лнца. А то, как до'лго пчела' виля'ет, сообща'ет, далеко' ли цветы'. Чем длинне'е та'нец, тем да'льше лете'ть. Е'сли же цветы' совсе'м бли'зко, пчела' про'сто кружи'тся на ме'сте. Его' называ'ют круговы'м та'нцем. Други'е пчёлы, внима'тельно следя'щие за та'нцем, тро'гают разве'дчицу у'сиками и запомина'ют за'пах цвето'в, принесённый е'ю. Пото'м они' вылета'ют из у'лья и безоши'бочно нахо'дят ну'жное ме'сто. Так за день пчёлы облета'ют ты'сячи цвето'в. Пчёлы да'рят лю'дям не то'лько мёд. Перелета'я с цветка' на цвето'к, они' перено'сят пыльцу', и благодаря' э'тому на дере'вьях появля'ются плоды'. Без пчёл у нас бы'ло бы гора'здо ме'ньше я'блок, ви'шен, огурцо'в и мно'гих други'х овоще'й и фру'ктов. Поэ'тому учёные во всём ми'ре беспоко'ятся, когда' пчёл стано'вится ме'ньше, и призыва'ют бере'чь э'тих тру'жениц.", [("разве'дчица", "Разве'дчица — э'то пчела', кото'рая пе'рвой нахо'дит цветы' и сообща'ет о них други'м."), ("со'ты", "Со'ты — э'то восковы'е яче'йки, в кото'рых пчёлы храня'т мёд."), ("пыльца'", "Пыльца' — э'то жёлтая пыль внутри' цветка'.")]),
 ("чарын", "В двухста'х киломе'трах к восто'ку от Алматы' нахо'дится одно' из са'мых удиви'тельных мест Казахста'на — Чары'нский каньо'н. Миллио'ны лет река' Чары'н, пробива'ющая себе' путь сквозь ска'лы, вымыва'ла мя'гкие поро'ды, и постепе'нно образова'лось глубо'кое уще'лье. Его' сте'ны места'ми поднима'ются почти' на три'ста ме'тров. Са'мая изве'стная часть каньо'на называ'ется Доли'ной за'мков. Ве'тер и дожди', века'ми обта'чивавшие ска'лы, преврати'ли их в ба'шни, сте'ны и купола', сло'вно постро'енные дре'вними архите'кторами. Когда' идёшь по дну доли'ны, ка'жется, что попа'л в заколдо'ванный го'род. Ка'мни здесь окра'шены в кра'сный, ора'нжевый и жёлтый цвета', и на зака'те они' горя'т, как раскалённые. Фото'графы специа'льно ждут ве'чера, что'бы пойма'ть э'ти кра'ски. Внизу', у са'мой реки', растёт ро'ща ре'дкого согди'йского я'сеня. Э'ти дере'вья, сохрани'вшиеся с леднико'вого пери'ода, мо'жно встре'тить лишь в немно'гих места'х плане'ты. Учёные называ'ют их живы'ми ископа'емыми. Ро'ща — настоя'щий зелёный оа'зис среди' раскалённых скал. Ка'ждый год Чары'н посеща'ют ты'сячи тури'стов, приезжа'ющих со всего' ми'ра. Что'бы сохрани'ть э'ту красоту', каньо'н объяви'ли национа'льным па'рком. Здесь нельзя' разводи'ть костры', лома'ть ве'тки и оставля'ть по'сле себя' му'сор. Ведь приро'да создава'ла э'тот го'род из ка'мня миллио'ны лет, а разру'шить его' мо'жно о'чень бы'стро.", [("каньо'н", "Каньо'н — э'то глубо'кое уще'лье с круты'ми сте'нами, кото'рое промы'ла река'."), ("обта'чивавшие", "Обта'чивавшие — зна'чит постепе'нно стира'вшие и сгла'живавшие."), ("живы'е ископа'емые", "Живы'е ископа'емые — э'то расте'ния и живо'тные, кото'рые почти' не измени'лись с дре'вних времён.")]),
 ("киты", "Си'ний кит — са'мое кру'пное живо'тное, кото'рое существова'ло на Земле' за всю её исто'рию. Он бо'льше любо'го диноза'вра! Длина' си'него кита' мо'жет достига'ть тридцати' ме'тров, а ве'сит он почти' как три'дцать слоно'в. Одно' его' се'рдце величино'й с ма'ленький автомоби'ль, а язы'к ве'сит, как це'лый слон. Несмотря' на огро'мные разме'ры, си'ний кит пита'ется кро'шечными рачка'ми, кото'рые называ'ются криль. Набира'я в пасть ты'сячи ли'тров воды', кит проце'живает её сквозь осо'бые пласти'ны, похо'жие на гре'бень. Вода' вытека'ет, а криль остаётся во рту. За день кит съеда'ет не'сколько тонн тако'й ме'лочи. Предста'вь, ско'лько э'то кро'шечных рачко'в! Хотя' киты' живу'т в воде', они' не ры'бы, а млекопита'ющие. Они' ды'шат во'здухом, поэ'тому то и де'ло поднима'ются к пове'рхности. Выдыха'я, кит выпуска'ет вверх фонта'н брызг высото'й почти' де'сять ме'тров. Детёныши кито'в пьют матери'нское молоко' и ка'ждый день прибавля'ют в ве'се почти' сто килогра'ммов. Ма'ма забо'тливо охраня'ет малыша' и не отплыва'ет от него' далеко'. Ещё одна' удиви'тельная осо'бенность кито'в — их пе'сни. Горба'тые киты' пою'т до'лгие и сло'жные мело'дии, кото'рые разно'сятся под водо'й на огро'мные расстоя'ния. Учёные до сих пор пыта'ются поня'ть, о чём пою'т э'ти морски'е велика'ны.", [("млекопита'ющие", "Млекопита'ющие — э'то живо'тные, кото'рые выка'рмливают детёнышей молоко'м."), ("криль", "Криль — э'то ме'лкие морски'е рачки'."), ("проце'живает", "Проце'живает — зна'чит пропуска'ет во'ду, а еду' заде'рживает.")]),
 ("молния", "Ты'сячи лет лю'ди боя'лись мо'лний, счита'я их гне'вом небе'сных бого'в. Одни'м из пе'рвых, кто разгада'л та'йну мо'лнии, был америка'нский учёный Бе'нджамин Фра'нклин. Он предположи'л, что мо'лния — э'то огро'мная электри'ческая и'скра, тако'го же ро'да, как та, что проска'кивает ме'жду па'льцем и дверно'й ру'чкой, е'сли до'лго ша'ркать нога'ми по ковру'. Что'бы прове'рить э'то, в ты'сяча семьсо'т пятьдеся'т второ'м году' Фра'нклин запусти'л в грозово'е не'бо возду'шного змея', к кото'рому был привя'зан металли'ческий ключ. Когда' над ним проплыва'ла ту'ча, от ключа' посы'пались и'скры. Дога'дка подтверди'лась! Э'тот о'пыт был смерте'льно опа'сным, и повторя'ть его' ни в ко'ем слу'чае нельзя'. Вско'ре Фра'нклин изобрёл громоотво'д. Э'то металли'ческий сте'ржень, устано'вленный на кры'ше и соединённый про'водом с землёй. Попада'я в него', мо'лния ухо'дит в зе'млю, не причиня'я вреда' зда'нию. Сего'дня громоотво'ды есть на мно'гих высо'ких зда'ниях. Учёные узна'ли о мо'лниях мно'го интере'сного. Вспы'шка дли'тся ме'ньше секу'нды, но во'здух вокру'г неё нагрева'ется сильне'е, чем пове'рхность Со'лнца. Раскалённый во'здух ре'зко расширя'ется, и мы слы'шим гро'хот, кото'рый называ'ется гро'мом. Е'сли гроза' заста'ла вас на откры'том ме'сте, нельзя' пря'таться под одино'ким де'ревом. Лу'чше присе'сть пони'же, пода'льше от высо'ких предме'тов.", [("громоотво'д", "Громоотво'д — э'то металли'ческий сте'ржень, кото'рый отво'дит мо'лнию в зе'млю."), ("и'скра", "И'скра — э'то ма'ленькая я'ркая вспы'шка.")]),
 ("шёлковый", "Две ты'сячи лет наза'д че'рез пусты'ни, сте'пи и го'ры протяну'лся Вели'кий шёлковый путь. Э'то была' не одна' доро'га, а це'лая сеть карава'нных доро'г, соединя'вшая Кита'й со стра'нами Средизе'много мо'ря. Своё назва'ние путь получи'л благодаря' шёлку, драгоце'нной тка'ни, секре'т изготовле'ния кото'рой зна'ли то'лько кита'йцы. Но по нему' везли' не то'лько шёлк. Карава'ны верблю'дов, нагру'женных тюка'ми, перевози'ли фарфо'р, пря'ности, драгоце'нные ка'мни, ковры' и лошаде'й. Обра'тно везли' зо'лото, серебро' и шерсть. Ва'жная часть Шёлкового пути' проходи'ла по террито'рии совреме'нного Казахста'на. Здесь стоя'ли бога'тые города' Тара'з, Отра'р и Сайра'м, где карава'ны остана'вливались на о'тдых. На постоя'лых двора'х купцы' корми'ли верблю'дов, обме'нивались това'рами и новостя'ми. Доро'га от Кита'я до Средизе'много мо'ря могла' занима'ть почти' год. Путеше'ственники страда'ли от жары' и жа'жды в пусты'нях, мёрзли на го'рных перева'лах и опаса'лись разбо'йников. Вме'сте с това'рами по Шёлковому пути' путеше'ствовали зна'ния, ска'зки, пе'сни и изобрете'ния. Так на За'пад попа'ли бума'га и по'рох, а на Восто'к пришли' стекло' и но'вые сорта' виногра'да. Сего'дня на ме'сте дре'вних городо'в рабо'тают архео'логи, находя'щие моне'ты, посу'ду и украше'ния. Ка'ждая така'я нахо'дка расска'зывает о вре'мени, когда' по на'шей степи' шли бесконе'чные карава'ны.", [("карава'н", "Карава'н — э'то верблю'ды и'ли ло'шади с гру'зом, кото'рые иду'т друг за дру'гом."), ("пря'ности", "Пря'ности — э'то души'стые припра'вы, наприме'р пе'рец и кори'ца."), ("архео'лог", "Архео'лог — э'то учёный, кото'рый раска'пывает следы' дре'вней жи'зни.")]),
 ("станция", "Высоко' над на'ми, на высоте' почти' в четы'реста киломе'тров, кружи'т вокру'г Земли' Междунаро'дная косми'ческая ста'нция. Она' лети'т так бы'стро, что облета'ет плане'ту всего' за полтора' часа'. Поэ'тому космона'вты, живу'щие на ста'нции, ка'ждые су'тки ви'дят шестна'дцать восхо'дов и шестна'дцать зака'тов. Ста'нцию стро'или мно'го лет учёные и инжене'ры ра'зных стран, доставля'я её ча'сти раке'тами и собира'я их пря'мо в ко'смосе. Тепе'рь э'то огро'мный дом разме'ром с футбо'льное по'ле. Жизнь на ста'нции совсе'м не похо'жа на земну'ю. Там цари'т невесо'мость, и всё, что не привя'зано, пла'вает в во'здухе. Что'бы не улете'ть во сне, космона'вты спят в спа'льных мешка'х, пристёгнутых к стене'. Во'ду они' пьют че'рез тру'бочку, ведь из ча'шки она' вы'плывет больши'м дрожа'щим ша'риком. Да'же причёсываться и чи'стить зу'бы прихо'дится осо'бым спо'собом. Ка'ждый день космона'вты по два часа' занима'ются спо'ртом на специа'льных тренажёрах. Без э'того их мы'шцы, отвы'кшие от нагру'зки, ста'ли бы сла'быми. Они' прово'дят нау'чные о'пыты, выра'щивают расте'ния и фотографи'руют Зе'млю. На ста'нции побыва'ли и космона'вты из Казахста'на. Гля'дя в иллюмина'тор, они' узнава'ли родны'е сте'пи, Каспи'йское мо'ре и Балха'ш. Кто зна'ет, мо'жет быть, когда' ты вы'растешь, туда' полети'шь и ты?", [("невесо'мость", "Невесо'мость — э'то когда' всё вокру'г пла'вает в во'здухе и ничего' не па'дает."), ("су'тки", "Су'тки — э'то день и ночь вме'сте, два'дцать четы'ре часа'."), ("тренажёр", "Тренажёр — э'то прибо'р для заня'тий спо'ртом.")]),
 ("беркутчи", "Ка'ждую зи'му де'душка Арма'на уезжа'л в го'ры на охо'ту с бе'ркутом. В э'том году' он впервы'е взял с собо'й вну'ка. Они' вы'ехали на рассве'те, когда' сне'жные верши'ны то'лько начина'ли розове'ть. На де'душкиной руке', оде'той в то'лстую ко'жаную перча'тку, сиде'ла Кара'. Э'то была' са'мка бе'ркута, ведь са'мки крупне'е и сильне'е самцо'в. На голове' у пти'цы был ко'жаный колпачо'к, закрыва'вший глаза'. — Заче'м он ей? — спроси'л Арма'н. — Что'бы Кара' не волнова'лась и не тра'тила си'лы зря, — объясни'л де'душка. — Когда' она' ничего' не ви'дит, она' споко'йна. Подня'вшись на высо'кий холм, они' до'лго осма'тривали доли'ну. Вдруг Арма'н заме'тил, как по сне'гу мелькну'ло ры'жее пятно'. — Лиса'! — прошепта'л он. Де'душка снял колпачо'к. Пти'ца, мгнове'нно уви'девшая добы'чу, сорвала'сь с руки' и ка'мнем ри'нулась вниз. Арма'н затаи'л дыха'ние. Лиса' мета'лась, пыта'ясь спря'таться, но Кара' была' быстре'е. Когда' они' спусти'лись, де'душка ла'сково погла'дил пти'цу и дал ей кусо'чек мя'са. — Бе'ркут не слуга', а друг и напа'рник, — сказа'л он. — Его' на'до уважа'ть и бере'чь. Мой оте'ц учи'л меня', а я научу' тебя'. Арма'н смотре'л на го'рдую пти'цу, сия'ющую в луча'х со'лнца, и понима'л, что э'тот день он запо'мнит на всю жизнь.", [("беркутчи'", "Беркутчи' — э'то охо'тник, кото'рый охо'тится вме'сте с ло'вчим бе'ркутом."), ("ри'нулась", "Ри'нулась — зна'чит стреми'тельно бро'силась."), ("напа'рник", "Напа'рник — э'то тот, с кем де'лаешь де'ло вдвоём.")]),
 ("звёзды", "В стари'ну коче'вники, пересека'вшие бескра'йнюю степь, не зна'ли ни карт, ни ко'мпасов. Доро'гу им пока'зывали звёзды. Об э'том Ерла'ну рассказа'л де'душка, когда' они' зи'мним ве'чером возвраща'лись на маши'не из сосе'днего ау'ла. Вдруг маши'на дёрнулась и загло'хла. Де'душка до'лго пыта'лся завести' мото'р, но всё бы'ло напра'сно. — Придётся идти' пешко'м, — вздохну'л он. — До ау'ла киломе'тра три. — А как мы найдём доро'гу? — испуга'лся Ерла'н. Вокру'г лежа'ла ро'вная бе'лая степь, и телефо'н не лови'л сеть. Де'душка по'днял го'лову к не'бу, усы'панному звёздами. — Ви'дишь семь я'рких звёзд, похо'жих на ковш? Каза'хи называ'ют их Семь разбо'йников. А вот э'та звезда', на кото'рую ука'зывают две кра'йние звезды' ковша', — Темирказы'к, Желе'зный кол. Она' всегда' стои'т на одно'м ме'сте, а остальны'е звёзды хо'дят вокру'г неё, как ко'ни, привя'занные к колу'. Наш ау'л на се'вере, зна'чит, идём пря'мо на неё. Они' шли, не своди' глаз с Темирказы'ка. Снег хрусте'л под нога'ми, моро'з щипа'л щёки, но Ерла'н бо'льше не боя'лся. Че'рез час впереди' засвети'лись огоньки' ау'ла. — Тепе'рь я зна'ю, что звёзды не то'лько краси'вые, — сказа'л Ерла'н, гре'ясь у пе'чки. — Они' ещё и настоя'щие помо'щники. — А ещё э'ту звезду' называ'ют Поля'рной, — улыбну'лся де'душка.", [("коче'вники", "Коче'вники — э'то наро'ды, кото'рые переезжа'ли со стада'ми с ме'ста на ме'сто."), ("загло'хла", "Загло'хла — зна'чит мото'р останови'лся и переста'л рабо'тать.")]),
 ("будильник", "Тиму'р счита'л, что гла'вный враг шко'льника — э'то у'тро. Ка'ждый день он выключа'л буди'льник, не открыва'я глаз, и сно'ва засыпа'л. Ма'ме приходи'лось буди'ть его' по три ра'за, и в шко'лу он прибега'л запыха'вшимся. Одна'жды Тиму'р реши'л поборо'ть э'ту беду' с по'мощью те'хники. Це'лые выходны'е он провёл в своём углу', зава'ленном провода'ми и дета'лями от ста'рых игру'шек. В воскресе'нье ве'чером изобрете'ние бы'ло гото'во. Э'то был буди'льник на колёсах. В шесть утра' он до'лжен был гро'мко зазвене'ть и уе'хать от крова'ти, что'бы Тиму'ру пришло'сь встать и догоня'ть его'. У'тром буди'льник срабо'тал отли'чно. Он зазвене'л так гро'мко, что подпры'гнул да'же кот, и бо'дро покати'лся по ко'мнате. Тиму'р, ещё не просну'вшийся, вскочи'л и бро'сился за ним. Буди'льник вы'ехал в коридо'р, разверну'лся у ку'хни и укати'лся под дива'н в гости'ной. Достава'я его', Тиму'р разбуди'л па'пу, па'па разбуди'л ма'му, а ма'ма разбуди'ла ба'бушку. В ито'ге за за'втраком сиде'ла вся семья', бо'драя и немно'го серди'тая. — Изобрете'ние, коне'чно, рабо'тает, — сказа'л па'па, зева'я. — Но в сле'дующий раз, пожа'луйста, приду'май буди'льник то'лько для одного' челове'ка. Тиму'р пообеща'л поду'мать. Зато' в тот день он впервы'е пришёл в шко'лу ра'ньше всех.", [("запыха'вшийся", "Запыха'вшийся — зна'чит тяжело' ды'шащий от бы'строго бе'га."), ("поборо'ть", "Поборо'ть — зна'чит победи'ть, одоле'ть.")]),
 ("марс", "Шёл две ты'сячи сто пятидеся'тый год. Двенадцатиле'тний Ая'н жил вме'сте с роди'телями на пе'рвой марсиа'нской ба'зе. Их дом, укры'тый прозра'чным ку'полом, стоя'л на краю' огро'много кра'тера. Снару'жи бы'ло хо'лодно и пу'сто, а во'здух был тако'й ре'дкий, что дыша'ть им бы'ло невозмо'жно. Поэ'тому выходи'ть за ку'пол мо'жно бы'ло то'лько в скафа'ндре. Бо'льше всего' Ая'н люби'л тепли'цу, где под я'ркими ла'мпами росли' помидо'ры, огурцы' и да'же ма'ленькая я'блонька, привезённая с Земли'. Ка'ждый день он полива'л её, разгова'ривая с ней, как с дру'гом. — Расти' быстре'е, — проси'л он. — Ты бу'дешь пе'рвой марсиа'нской я'блоней. Одна'жды ве'чером, гля'дя в окно' на ры'жую пусты'ню, Ая'н заме'тил на не'бе ма'ленькую голубу'ю звёздочку. — Э'то Земля', — сказа'ла ма'ма, подойдя' к нему'. — Там живёт твоя' ба'бушка. Ая'н до'лго смотре'л на звёздочку. Он никогда' не был на Земле' и знал её то'лько по фи'льмам и ба'бушкиным расска'зам о степя'х, река'х и ле'тнем дожде'. — Когда' я'блонька даст пе'рвые я'блоки, я отвезу' одно' ба'бушке, — реши'л Ая'н. — Пусть попро'бует марсиа'нское я'блоко! А весно'й, кото'рая на Ма'рсе дли'тся бо'льше полуго'да, на я'блоньке распусти'лся пе'рвый бе'лый цвето'к.", [("ку'пол", "Ку'пол — э'то кру'глая кры'ша, похо'жая на перевёрнутую ча'шку."), ("скафа'ндр", "Скафа'ндр — э'то костю'м космона'вта, в кото'ром мо'жно дыша'ть."), ("тепли'ца", "Тепли'ца — э'то тёплый дом для расте'ний.")]),
 ("динозавры", "Диноза'вры появи'лись на Земле' о'коло двухсо'т тридцати' миллио'нов лет наза'д и бо'лее ста пяти'десяти миллио'нов лет бы'ли хозя'евами плане'ты. Сло'во диноза'вр означа'ет стра'шный я'щер. Среди' них бы'ли и настоя'щие гига'нты, и малыши' величино'й с ку'рицу. Огро'мные травоя'дные диноза'вры, таки'е как брахиоза'вр, могли' дотяну'ться до верху'шек высо'ких дере'вьев. А хи'щный тиранноза'вр, облада'вший мо'щными челюстя'ми, мог раскуси'ть ко'сти свое'й добы'чи. Отку'да мы э'то зна'ем? Ведь ни оди'н челове'к никогда' не ви'дел живо'го диноза'вра. Всё, что изве'стно о них, учёные узна'ли по окамене'лостям. Так называ'ют ко'сти, зу'бы, я'йца и да'же следы', кото'рые за миллио'ны лет преврати'лись в ка'мень. Иссле'дуя их, палеонто'логи восстана'вливают вне'шний вид живо'тных, узнаю'т, чем они' пита'лись и как дви'гались. Оста'тки диноза'вров находи'ли и в Казахста'не, наприме'р недалеко' от Ара'льского мо'ря. На'йденного там я'щера назва'ли аралоза'вром. О'коло шести'десяти шести' миллио'нов лет наза'д на Зе'млю упа'л огро'мный астеро'ид. Подня'вшаяся пыль на мно'го лет закры'ла Со'лнце, ста'ло хо'лодно, и диноза'вры вы'мерли. Но не все! Учёные счита'ют, что пти'цы — э'то пото'мки ма'леньких хи'щных диноза'вров. Так что, кормя' голубе'й в па'рке, вы, мо'жет быть, ко'рмите их далёких ро'дственников.", [("окамене'лости", "Окамене'лости — э'то оста'тки дре'вних живо'тных и расте'ний, кото'рые преврати'лись в ка'мень."), ("астеро'ид", "Астеро'ид — э'то огро'мная косми'ческая глы'ба."), ("пото'мки", "Пото'мки — э'то де'ти, вну'ки и пра'внуки.")]),
 ("балхаш", "В Казахста'не раски'нулось одно' из са'мых необы'чных озёр в ми'ре — Балха'ш. Его' длина' бо'лее шестисо'т киломе'тров, и е'сли стоя'ть на берегу', ка'жется, что пе'ред тобо'й мо'ре. В ве'треную пого'ду по нему' хо'дят настоя'щие морски'е во'лны. Но гла'вная зага'дка Балха'ша в друго'м. Его' за'падная полови'на пре'сная, а восто'чная солонова'тая. Как тако'е возмо'жно? Всё де'ло в том, что о'зеро почти' разделено' на две ча'сти у'зким проли'вом. В за'падную часть впада'ет полново'дная река' И'ли, принося'щая с гор чи'стую пре'сную во'ду. А в восто'чную часть впада'ют то'лько небольши'е ре'чки. Вода' там си'льно испаря'ется на жа'рком со'лнце, а со'ли остаю'тся, и поэ'тому она' стано'вится солоне'е. Проли'в же так у'зок, что во'ды двух полови'н почти' не переме'шиваются. По берега'м Балха'ша гнездя'тся ты'сячи птиц, среди' кото'рых ца'пли, бакла'ны и пелика'ны. Ле'том сюда' приезжа'ют отдыха'ющие, что'бы попла'вать в тёплой воде' и порыба'чить. А зимо'й о'зеро покрыва'ется то'лстым льдом, и по нему' мо'жно ката'ться на конька'х. Но о'зеру грози'т опа'сность. Е'сли забира'ть из И'ли сли'шком мно'го воды' для поле'й и заво'дов, Балха'ш мо'жет обмеле'ть, как э'то случи'лось с Ара'льским мо'рем. Поэ'тому учёные внима'тельно следя'т за у'ровнем воды' и напомина'ют, что приро'ду на'до бере'чь.", [("проли'в", "Проли'в — э'то у'зкая полоса' воды', соединя'ющая два водоёма."), ("пре'сная", "Пре'сная вода' — э'то вода' без со'ли, её мо'жно пить."), ("солонова'тая", "Солонова'тая — зна'чит немно'го солёная.")]),
]
